package domain

import (
	"bytes"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"path/filepath"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"

	internalerrors "github.com/skillicinski/bo/internal/errors"
)

type State struct {
	Sources               []SourceRecord       `json:"sources"`
	DistillationDocuments []DistillationRecord `json:"distillation_documents,omitempty"`
}

// SourceRecord is the aggregate for one exact source identity.
type SourceRecord struct {
	SourceKey string         `json:"source_key"`
	Snapshots []RawRecord    `json:"snapshots"`
	Summary   *SummaryRecord `json:"summary,omitempty"`
}

type RawRecord struct {
	Filename          string    `json:"filename"`
	WrittenAt         time.Time `json:"written_at"`
	ContentDigest     string    `json:"content_digest,omitempty"`
	ContentSize       *int64    `json:"content_size,omitempty"`
	ContentModifiedAt string    `json:"content_modified_at,omitempty"`
}

type SummaryRecord struct {
	Filename          string    `json:"filename"`
	DerivedFrom       string    `json:"derived_from"`
	CreatedAt         time.Time `json:"created_at"`
	UpdatedAt         time.Time `json:"updated_at"`
	ContentDigest     string    `json:"content_digest,omitempty"`
	ContentSize       *int64    `json:"content_size,omitempty"`
	ContentModifiedAt string    `json:"content_modified_at,omitempty"`
}

type DistillationInput struct {
	SourceKey     string       `json:"source_key"`
	Kind          DocumentKind `json:"kind"`
	Filename      string       `json:"filename"`
	ContentDigest string       `json:"content_digest"`
}

type DistillationRecord struct {
	Filename          string              `json:"filename"`
	Topic             string              `json:"topic,omitempty"`
	Kind              DocumentKind        `json:"kind"`
	CreatedAt         time.Time           `json:"created_at"`
	UpdatedAt         time.Time           `json:"updated_at"`
	ContentDigest     string              `json:"content_digest,omitempty"`
	ContentSize       *int64              `json:"content_size,omitempty"`
	ContentModifiedAt string              `json:"content_modified_at,omitempty"`
	DerivedFrom       []DistillationInput `json:"derived_from"`
}

func (s State) MarshalJSON() ([]byte, error) {
	if err := s.Validate(); err != nil {
		return nil, err
	}
	sources := make([]SourceRecord, len(s.Sources))
	copy(sources, s.Sources)
	for index := range sources {
		if sources[index].Snapshots == nil {
			sources[index].Snapshots = []RawRecord{}
		}
	}
	var distillation *[]DistillationRecord
	if s.DistillationDocuments != nil {
		value := append([]DistillationRecord{}, s.DistillationDocuments...)
		distillation = &value
	}
	return json.Marshal(struct {
		Sources               []SourceRecord        `json:"sources"`
		DistillationDocuments *[]DistillationRecord `json:"distillation_documents,omitempty"`
	}{Sources: sources, DistillationDocuments: distillation})
}

func MarshalState(state State) ([]byte, error) {
	data, err := json.MarshalIndent(state, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(data, '\n'), nil
}

func UnmarshalState(data []byte) (State, error) {
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	var state State
	if err := decoder.Decode(&state); err != nil {
		return State{}, internalerrors.Wrap(internalerrors.KindValidation, "invalid state", err)
	}
	var extra any
	if err := decoder.Decode(&extra); err != io.EOF {
		if err == nil {
			return State{}, internalerrors.Validation("state contains multiple JSON values")
		}
		return State{}, internalerrors.Wrap(internalerrors.KindValidation, "invalid state", err)
	}
	if state.Sources == nil {
		state.Sources = []SourceRecord{}
	}
	for index := range state.Sources {
		if state.Sources[index].Snapshots == nil {
			state.Sources[index].Snapshots = []RawRecord{}
		}
	}
	if err := state.Validate(); err != nil {
		return State{}, err
	}
	return state, nil
}

func (s State) Validate() error {
	sourceKeys := make(map[string]struct{}, len(s.Sources))
	rawFilenames := make(map[string]string)
	summaryFilenames := make(map[string]string)
	for sourceIndex, source := range s.Sources {
		if err := ValidateSourceKey(source.SourceKey); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("sources[%d].source_key", sourceIndex), err)
		}
		if _, exists := sourceKeys[source.SourceKey]; exists {
			return internalerrors.Validation(fmt.Sprintf("sources[%d].source_key: duplicate source key %q", sourceIndex, source.SourceKey))
		}
		sourceKeys[source.SourceKey] = struct{}{}

		snapshots := make(map[string]struct{}, len(source.Snapshots))
		for snapshotIndex, snapshot := range source.Snapshots {
			if err := ValidateDocumentName(snapshot.Filename); err != nil {
				return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("sources[%d].snapshots[%d].filename", sourceIndex, snapshotIndex), err)
			}
			if _, exists := snapshots[snapshot.Filename]; exists {
				return internalerrors.Validation(fmt.Sprintf("sources[%d].snapshots[%d].filename: duplicate snapshot filename %q", sourceIndex, snapshotIndex, snapshot.Filename))
			}
			if previous, exists := rawFilenames[snapshot.Filename]; exists {
				return internalerrors.Validation(fmt.Sprintf("sources[%d].snapshots[%d].filename: already used by %s", sourceIndex, snapshotIndex, previous))
			}
			snapshots[snapshot.Filename] = struct{}{}
			rawFilenames[snapshot.Filename] = fmt.Sprintf("sources[%d].snapshots[%d]", sourceIndex, snapshotIndex)
			if err := ValidateTimestamp(snapshot.WrittenAt); err != nil {
				return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("sources[%d].snapshots[%d].written_at", sourceIndex, snapshotIndex), err)
			}
			if err := validateDocumentBaseline(snapshot.ContentDigest, snapshot.ContentSize, snapshot.ContentModifiedAt); err != nil {
				return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("sources[%d].snapshots[%d].content_baseline", sourceIndex, snapshotIndex), err)
			}
		}

		if source.Summary == nil {
			continue
		}
		summary := source.Summary
		if err := ValidateDocumentName(summary.Filename); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("sources[%d].summary.filename", sourceIndex), err)
		}
		if previous, exists := summaryFilenames[summary.Filename]; exists {
			return internalerrors.Validation(fmt.Sprintf("sources[%d].summary.filename: already used by %s", sourceIndex, previous))
		}
		summaryFilenames[summary.Filename] = fmt.Sprintf("sources[%d].summary", sourceIndex)
		if err := ValidateDocumentName(summary.DerivedFrom); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("sources[%d].summary.derived_from", sourceIndex), err)
		}
		if _, exists := snapshots[summary.DerivedFrom]; !exists {
			return internalerrors.Validation(fmt.Sprintf("sources[%d].summary.derived_from: snapshot %q does not exist for source %q", sourceIndex, summary.DerivedFrom, source.SourceKey))
		}
		if err := ValidateTimestamp(summary.CreatedAt); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("sources[%d].summary.created_at", sourceIndex), err)
		}
		if err := ValidateTimestamp(summary.UpdatedAt); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("sources[%d].summary.updated_at", sourceIndex), err)
		}
		if summary.UpdatedAt.Before(summary.CreatedAt) {
			return internalerrors.Validation(fmt.Sprintf("sources[%d].summary.updated_at: before created_at", sourceIndex))
		}
		if err := validateDocumentBaseline(summary.ContentDigest, summary.ContentSize, summary.ContentModifiedAt); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("sources[%d].summary.content_baseline", sourceIndex), err)
		}
	}
	distillationFilenames := make(map[string]string, len(s.DistillationDocuments))
	distillationTopics := make(map[string]string, len(s.DistillationDocuments))
	for index, record := range s.DistillationDocuments {
		if err := ValidateDocumentName(record.Filename); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("distillation_documents[%d].filename", index), err)
		}
		if previous, exists := distillationFilenames[record.Filename]; exists {
			return internalerrors.Validation(fmt.Sprintf("distillation_documents[%d].filename: already used by %s", index, previous))
		}
		distillationFilenames[record.Filename] = fmt.Sprintf("distillation_documents[%d]", index)
		if err := ValidateTopic(record.Topic); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("distillation_documents[%d].topic", index), err)
		}
		if previous, exists := distillationTopics[record.Topic]; exists {
			return internalerrors.Validation(fmt.Sprintf("distillation_documents[%d].topic: already used by %s", index, previous))
		}
		distillationTopics[record.Topic] = fmt.Sprintf("distillation_documents[%d]", index)
		if record.Kind != DocumentKindDistillation {
			return internalerrors.Validation(fmt.Sprintf("distillation_documents[%d].kind: invalid distillation kind %q", index, record.Kind))
		}
		if err := ValidateTimestamp(record.CreatedAt); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("distillation_documents[%d].created_at", index), err)
		}
		if err := ValidateTimestamp(record.UpdatedAt); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("distillation_documents[%d].updated_at", index), err)
		}
		if record.UpdatedAt.Before(record.CreatedAt) {
			return internalerrors.Validation(fmt.Sprintf("distillation_documents[%d].updated_at: before created_at", index))
		}
		if err := validateDocumentBaseline(record.ContentDigest, record.ContentSize, record.ContentModifiedAt); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("distillation_documents[%d].content_baseline", index), err)
		}
		if len(record.DerivedFrom) < 1 {
			return internalerrors.Validation(fmt.Sprintf("distillation_documents[%d].derived_from: must not be empty", index))
		}
		inputKeys := make(map[string]struct{}, len(record.DerivedFrom))
		distinctSources := make(map[string]struct{}, len(record.DerivedFrom))
		for inputIndex, input := range record.DerivedFrom {
			if err := ValidateSourceKey(input.SourceKey); err != nil {
				return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("distillation_documents[%d].derived_from[%d].source_key", index, inputIndex), err)
			}
			if input.Kind != DocumentKindRaw && input.Kind != DocumentKindSummary {
				return internalerrors.Validation(fmt.Sprintf("distillation_documents[%d].derived_from[%d].kind: invalid document kind %q", index, inputIndex, input.Kind))
			}
			if err := ValidateDocumentName(input.Filename); err != nil {
				return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("distillation_documents[%d].derived_from[%d].filename", index, inputIndex), err)
			}
			if err := validateDigest(input.ContentDigest); err != nil {
				return internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("distillation_documents[%d].derived_from[%d].content_digest", index, inputIndex), err)
			}
			key := fmt.Sprintf("%s\x00%s\x00%s", input.SourceKey, input.Kind, input.Filename)
			if _, exists := inputKeys[key]; exists {
				return internalerrors.Validation(fmt.Sprintf("distillation_documents[%d].derived_from[%d]: duplicate input", index, inputIndex))
			}
			inputKeys[key] = struct{}{}
			distinctSources[input.SourceKey] = struct{}{}
			if !s.ContainsDocument(input) {
				return internalerrors.Validation(fmt.Sprintf("distillation_documents[%d].derived_from[%d]: document %q does not belong to source %q", index, inputIndex, input.Filename, input.SourceKey))
			}
		}
		if len(distinctSources) < 2 {
			return internalerrors.Validation(fmt.Sprintf("distillation_documents[%d].derived_from: must contain at least two source identities", index))
		}
	}
	return nil
}

func validateDigest(digest string) error {
	if len(digest) != sha256.Size*2 {
		return internalerrors.Validation("document content digest must be a SHA-256 hex digest")
	}
	if _, err := hex.DecodeString(digest); err != nil {
		return internalerrors.Validation("document content digest must be a SHA-256 hex digest")
	}
	return nil
}

// ContainsDocument reports whether input names a document in its source aggregate.
func (s State) ContainsDocument(input DistillationInput) bool {
	for _, source := range s.Sources {
		if source.SourceKey != input.SourceKey {
			continue
		}
		switch input.Kind {
		case DocumentKindRaw:
			for _, snapshot := range source.Snapshots {
				if snapshot.Filename == input.Filename {
					return true
				}
			}
		case DocumentKindSummary:
			return source.Summary != nil && source.Summary.Filename == input.Filename
		}
	}
	return false
}

// ValidateContentDigest validates a document content digest.
func ValidateContentDigest(digest string) error { return validateDigest(digest) }

func ValidateSourceKey(sourceKey string) error {
	if sourceKey == "" {
		return internalerrors.Validation("source key must not be empty")
	}
	if strings.HasPrefix(sourceKey, "raw:") {
		if err := ValidateDocumentName(strings.TrimPrefix(sourceKey, "raw:")); err != nil {
			return internalerrors.Wrap(internalerrors.KindValidation, "raw source key must contain a document name", err)
		}
		return nil
	}
	parsed, err := url.Parse(sourceKey)
	if err != nil || parsed.Host == "" || (parsed.Scheme != "http" && parsed.Scheme != "https") {
		return internalerrors.Validation("source key must be an http or https URL or raw:<filename>")
	}
	if parsed.User != nil {
		return internalerrors.Validation("source key URL must not contain user information")
	}
	if parsed.Fragment != "" || strings.Contains(sourceKey, "#") {
		return internalerrors.Validation("source key URL must not contain a fragment")
	}
	if credentialQueryParameter(parsed.RawQuery) {
		return internalerrors.Validation("source key URL must not contain credential query parameters")
	}
	for _, r := range sourceKey {
		if unicode.IsControl(r) || unicode.IsSpace(r) {
			return internalerrors.Validation("source key must not contain whitespace or control characters")
		}
	}
	return nil
}

func credentialQueryParameter(rawQuery string) bool {
	if rawQuery == "" {
		return false
	}
	values, err := url.ParseQuery(rawQuery)
	if err != nil {
		return true
	}
	for key := range values {
		normalized := strings.ToLower(strings.ReplaceAll(key, "-", "_"))
		if strings.HasPrefix(normalized, "x_amz_") || strings.HasPrefix(normalized, "x_goog_") {
			return true
		}
		switch normalized {
		case "api_key", "apikey", "auth", "authorization", "key", "jwt", "oauth", "password", "passwd", "secret", "sig", "signature", "token":
			return true
		}
		for _, marker := range []string{"access_token", "credential", "password", "secret", "signature", "token"} {
			if strings.Contains(normalized, marker) {
				return true
			}
		}
	}
	return false
}

func ValidateDocumentName(name string) error {
	if !utf8.ValidString(name) || name == "" || name == "." || name == ".." || strings.ContainsAny(name, `/\`) || strings.ContainsRune(name, 0) ||
		!strings.EqualFold(filepath.Ext(name), ".md") {
		return internalerrors.Validation("document name must be a Markdown file name")
	}
	for _, r := range name {
		if unicode.IsControl(r) {
			return internalerrors.Validation("document name must not contain control characters")
		}
	}
	return nil
}

func CanonicalTopic(topic string) (string, error) {
	topic = strings.TrimSpace(topic)
	var builder strings.Builder
	lastDash := false
	for _, r := range topic {
		if unicode.IsControl(r) {
			return "", internalerrors.Validation("topic must not contain control characters")
		}
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			builder.WriteRune(unicode.ToLower(r))
			lastDash = false
		} else if builder.Len() > 0 && !lastDash {
			builder.WriteByte('-')
			lastDash = true
		}
	}
	canonical := strings.TrimRight(builder.String(), "-")
	if canonical == "" {
		return "", internalerrors.Validation("topic must contain letters or digits")
	}
	return canonical, nil
}

func ValidateTopic(topic string) error {
	canonical, err := CanonicalTopic(topic)
	if err != nil {
		return err
	}
	if topic != canonical {
		return internalerrors.Validation("topic must use canonical kebab-case")
	}
	return nil
}

func ValidateTimestamp(timestamp time.Time) error {
	if timestamp.IsZero() {
		return internalerrors.Validation("timestamp must not be zero")
	}
	if _, offset := timestamp.Zone(); offset != 0 {
		return internalerrors.Validation("timestamp must use UTC")
	}
	return nil
}

func validateDocumentBaseline(digest string, size *int64, modifiedAt string) error {
	if size != nil && *size < 0 {
		return internalerrors.Validation("document content size must not be negative")
	}
	if digest == "" && size == nil && modifiedAt == "" {
		return nil
	}
	if digest == "" || size == nil || modifiedAt == "" {
		return internalerrors.Validation("document content baseline must include digest, size, and modification time")
	}
	if len(digest) != sha256.Size*2 {
		return internalerrors.Validation("document content digest must be a SHA-256 hex digest")
	}
	if _, err := hex.DecodeString(digest); err != nil {
		return internalerrors.Validation("document content digest must be a SHA-256 hex digest")
	}
	timestamp, err := time.Parse(time.RFC3339Nano, modifiedAt)
	if err != nil {
		return internalerrors.Validation("document content modification time must be RFC 3339")
	}
	if err := ValidateTimestamp(timestamp); err != nil {
		return internalerrors.Validation("document content modification time must use UTC")
	}
	return nil
}
package domain

import (
	"strings"
	"time"

	internalerrors "github.com/skillicinski/bo/internal/errors"
)

// SnapshotCommit is the storage-neutral data for one raw document commit.
type SnapshotCommit struct {
	SourceKey string
	Filename  string
	WrittenAt time.Time
	Contents  []byte
	Event     Operation
}

// SummaryCommit is the storage-neutral data for one summary commit.
type SummaryCommit struct {
	SourceKey    string
	Filename     string
	DerivedFrom  string
	RawWrittenAt time.Time
	CreatedAt    time.Time
	UpdatedAt    time.Time
	Contents     []byte
	Event        Operation
}

// DistillationCommit is the storage-neutral data for one distillation commit.
type DistillationCommit struct {
	Kind        DocumentKind
	Filename    string
	Topic       string
	Update      bool
	CreatedAt   time.Time
	UpdatedAt   time.Time
	DerivedFrom []DistillationInput
	Contents    []byte
	Event       Operation
}

// ValidateDocumentKind validates a workspace document kind.
func ValidateDocumentKind(kind DocumentKind) error {
	if kind != DocumentKindRaw && kind != DocumentKindSummary && kind != DocumentKindDistillation {
		return internalerrors.Validation("unsupported document kind")
	}
	return nil
}

func (commit SnapshotCommit) Validate() error {
	if err := ValidateSourceKey(commit.SourceKey); err != nil {
		return err
	}
	if err := ValidateDocumentName(commit.Filename); err != nil {
		return err
	}
	if err := ValidateTimestamp(commit.WrittenAt); err != nil {
		return err
	}
	return validateMutationEvent(commit.Event, CommandSnap, commit.SourceKey, DocumentKindRaw, commit.Filename, nil)
}

func (commit SummaryCommit) Validate() error {
	if err := ValidateSourceKey(commit.SourceKey); err != nil {
		return err
	}
	if err := ValidateDocumentName(commit.Filename); err != nil {
		return err
	}
	if err := ValidateDocumentName(commit.DerivedFrom); err != nil {
		return err
	}
	if err := ValidateTimestamp(commit.RawWrittenAt); err != nil {
		return err
	}
	if err := ValidateTimestamp(commit.CreatedAt); err != nil {
		return err
	}
	if err := ValidateTimestamp(commit.UpdatedAt); err != nil {
		return err
	}
	return validateMutationEvent(commit.Event, CommandWriteSummary, commit.SourceKey, DocumentKindSummary, commit.Filename, &summaryEventProvenance{
		derivedFrom:  commit.DerivedFrom,
		rawWrittenAt: commit.RawWrittenAt,
	})
}

func (commit DistillationCommit) Validate() error {
	if commit.Kind != DocumentKindDistillation {
		return internalerrors.Validation("invalid distillation kind")
	}
	if err := ValidateDocumentName(commit.Filename); err != nil {
		return err
	}
	if err := ValidateTopic(commit.Topic); err != nil {
		return err
	}
	if err := ValidateTimestamp(commit.CreatedAt); err != nil {
		return err
	}
	if err := ValidateTimestamp(commit.UpdatedAt); err != nil {
		return err
	}
	if commit.UpdatedAt.Before(commit.CreatedAt) {
		return internalerrors.Validation("distillation updated_at is before created_at")
	}
	if len(commit.DerivedFrom) == 0 {
		return internalerrors.Validation("distillation document must have inputs")
	}
	if strings.TrimSpace(string(commit.Contents)) == "" {
		return internalerrors.Validation("distillation document must be non-empty")
	}
	for _, input := range commit.DerivedFrom {
		if input.Kind != DocumentKindRaw && input.Kind != DocumentKindSummary {
			return internalerrors.Validation("invalid distillation input kind")
		}
		if err := ValidateSourceKey(input.SourceKey); err != nil {
			return err
		}
		if err := ValidateDocumentName(input.Filename); err != nil {
			return err
		}
		if err := ValidateContentDigest(input.ContentDigest); err != nil {
			return err
		}
	}
	return validateMutationEvent(commit.Event, CommandWriteDistillation, "", DocumentKindDistillation, commit.Filename, nil)
}

type summaryEventProvenance struct {
	derivedFrom  string
	rawWrittenAt time.Time
}

func validateMutationEvent(event Operation, command OperationCommand, sourceKey string, kind DocumentKind, filename string, provenance *summaryEventProvenance) error {
	if err := event.Validate(); err != nil {
		return internalerrors.Wrap(internalerrors.KindValidation, "invalid mutation event", err)
	}
	if event.Command != command {
		return internalerrors.Validation("mutation event command does not match commit")
	}
	if event.Outcome != OutcomeCommitted || event.Error != nil {
		return internalerrors.Validation("mutation event must be committed without an error")
	}
	if command == CommandWriteDistillation {
		if event.Source != nil || event.Provenance != nil {
			return internalerrors.Validation("distillation mutation event must not contain source or provenance")
		}
	} else if event.Source == nil || event.Source.SourceKey != sourceKey {
		return internalerrors.Validation("mutation event source does not match commit")
	}
	if event.Document == nil || event.Document.Kind != kind || event.Document.Filename != filename {
		return internalerrors.Validation("mutation event document does not match commit")
	}
	if provenance == nil {
		if event.Provenance != nil {
			return internalerrors.Validation("mutation event provenance is not allowed")
		}
		return nil
	}
	if event.Provenance == nil || event.Provenance.DerivedFrom == nil ||
		event.Provenance.DerivedFrom.Kind != DocumentKindRaw ||
		event.Provenance.DerivedFrom.Filename != provenance.derivedFrom ||
		event.Provenance.RawWrittenAt == nil ||
		!event.Provenance.RawWrittenAt.Equal(provenance.rawWrittenAt) {
		return internalerrors.Validation("mutation event provenance does not match commit")
	}
	return nil
}

// ApplySnapshot returns the state after a validated raw document commit.
func (s State) ApplySnapshot(commit SnapshotCommit) (State, error) {
	next := cloneState(s)
	for index := range next.Sources {
		if next.Sources[index].SourceKey != commit.SourceKey {
			continue
		}
		for _, snapshot := range next.Sources[index].Snapshots {
			if snapshot.Filename == commit.Filename {
				return State{}, internalerrors.AlreadyExists("snapshot already belongs to workspace state")
			}
		}
		next.Sources[index].Snapshots = append(next.Sources[index].Snapshots, RawRecord{Filename: commit.Filename, WrittenAt: commit.WrittenAt})
		return next, next.Validate()
	}
	next.Sources = append(next.Sources, SourceRecord{
		SourceKey: commit.SourceKey,
		Snapshots: []RawRecord{{Filename: commit.Filename, WrittenAt: commit.WrittenAt}},
	})
	return next, next.Validate()
}

// ApplySummary returns the state after a validated summary commit.
func (s State) ApplySummary(commit SummaryCommit) (State, error) {
	next := cloneState(s)
	record := &SummaryRecord{Filename: commit.Filename, DerivedFrom: commit.DerivedFrom, CreatedAt: commit.CreatedAt, UpdatedAt: commit.UpdatedAt}
	for index := range next.Sources {
		if next.Sources[index].SourceKey != commit.SourceKey {
			continue
		}
		if !hasSnapshot(next.Sources[index].Snapshots, commit.DerivedFrom) {
			if len(next.Sources[index].Snapshots) != 0 {
				return State{}, internalerrors.Validation("summary must derive from a workspace snapshot")
			}
			next.Sources[index].Snapshots = []RawRecord{{Filename: commit.DerivedFrom, WrittenAt: commit.RawWrittenAt}}
		}
		if next.Sources[index].Summary != nil && next.Sources[index].Summary.Filename != commit.Filename {
			return State{}, internalerrors.Validation("summary filename cannot change")
		}
		next.Sources[index].Summary = record
		return next, next.Validate()
	}
	next.Sources = append(next.Sources, SourceRecord{
		SourceKey: commit.SourceKey,
		Snapshots: []RawRecord{{Filename: commit.DerivedFrom, WrittenAt: commit.RawWrittenAt}},
		Summary:   record,
	})
	return next, next.Validate()
}

// ApplyDistillation returns the state after a validated distillation commit.
func (s State) ApplyDistillation(commit DistillationCommit) (State, error) {
	next := cloneState(s)
	record := DistillationRecord{
		Filename: commit.Filename, Topic: commit.Topic, Kind: commit.Kind,
		CreatedAt: commit.CreatedAt, UpdatedAt: commit.UpdatedAt,
		DerivedFrom: append([]DistillationInput(nil), commit.DerivedFrom...),
	}
	for index := range next.DistillationDocuments {
		if next.DistillationDocuments[index].Filename != commit.Filename {
			continue
		}
		if !commit.Update {
			return State{}, internalerrors.AlreadyExists("distillation document already belongs to workspace state")
		}
		if next.DistillationDocuments[index].Topic != record.Topic {
			return State{}, internalerrors.Validation("distillation topic cannot change on update")
		}
		record.CreatedAt = next.DistillationDocuments[index].CreatedAt
		next.DistillationDocuments[index] = record
		return next, next.Validate()
	}
	if commit.Update {
		return State{}, internalerrors.Conflict("distillation document exists outside workspace state")
	}
	next.DistillationDocuments = append(next.DistillationDocuments, record)
	return next, next.Validate()
}

func cloneState(state State) State {
	next := State{Sources: make([]SourceRecord, len(state.Sources))}
	if state.DistillationDocuments != nil {
		next.DistillationDocuments = make([]DistillationRecord, len(state.DistillationDocuments))
	}
	for index, source := range state.Sources {
		next.Sources[index] = SourceRecord{SourceKey: source.SourceKey, Snapshots: append([]RawRecord(nil), source.Snapshots...)}
		if source.Summary != nil {
			summary := *source.Summary
			next.Sources[index].Summary = &summary
		}
	}
	for index, record := range state.DistillationDocuments {
		next.DistillationDocuments[index] = record
		next.DistillationDocuments[index].DerivedFrom = append([]DistillationInput(nil), record.DerivedFrom...)
	}
	return next
}

func hasSnapshot(snapshots []RawRecord, filename string) bool {
	for _, snapshot := range snapshots {
		if snapshot.Filename == filename {
			return true
		}
	}
	return false
}
package domain

import (
	"crypto/rand"
	"fmt"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"

	internalerrors "github.com/skillicinski/bo/internal/errors"
)

type OperationCommand string

const (
	CommandSeed              OperationCommand = "seed"
	CommandSnap              OperationCommand = "snap"
	CommandState             OperationCommand = "state"
	CommandSynth             OperationCommand = "synth"
	CommandDistill           OperationCommand = "distill"
	CommandWriteSummary      OperationCommand = "write_summary"
	CommandWriteDistillation OperationCommand = "write_distillation"
)

type OperationOutcome string

const (
	OutcomeCommitted OperationOutcome = "committed"
	OutcomeFailed    OperationOutcome = "failed"
)

type SourceIdentity struct {
	SourceKey string `json:"source_key"`
}

type DocumentIdentity struct {
	Kind     DocumentKind `json:"kind"`
	Filename string       `json:"filename"`
}

type OperationProvenance struct {
	DerivedFrom  *DocumentIdentity `json:"derived_from,omitempty"`
	RawWrittenAt *time.Time        `json:"raw_written_at,omitempty"`
}

type OperationError struct {
	Kind      string `json:"kind"`
	Retryable bool   `json:"retryable"`
}

type TokenUsage struct {
	PromptTokens     int `json:"prompt_tokens"`
	CompletionTokens int `json:"completion_tokens"`
	TotalTokens      int `json:"total_tokens"`
	ThoughtsTokens   int `json:"thoughts_tokens,omitempty"`
}

type OperationMetrics struct {
	Turns               int           `json:"turns"`
	ToolCalls           int           `json:"tool_calls"`
	Duration            time.Duration `json:"duration"`
	SummariesWritten    int           `json:"summaries_written"`
	SummariesSkipped    int           `json:"summaries_skipped"`
	DistillationWritten int           `json:"distillation_written,omitempty"`
	DistillationSkipped int           `json:"distillation_skipped,omitempty"`
	Usage               *TokenUsage   `json:"usage,omitempty"`
}

// Operation is a durable, typed application event.
type Operation struct {
	OperationID string               `json:"operation_id"`
	Attempt     int                  `json:"attempt"`
	Timestamp   string               `json:"timestamp"`
	Actor       string               `json:"actor"`
	Command     OperationCommand     `json:"command"`
	Outcome     OperationOutcome     `json:"outcome"`
	Source      *SourceIdentity      `json:"source,omitempty"`
	Document    *DocumentIdentity    `json:"document,omitempty"`
	Provenance  *OperationProvenance `json:"provenance,omitempty"`
	Error       *OperationError      `json:"error,omitempty"`
	Metrics     *OperationMetrics    `json:"metrics,omitempty"`
}

func NewOperationID() string {
	return "op-" + rand.Text()
}

func (o *Operation) Normalize() {
	if o.OperationID == "" {
		o.OperationID = NewOperationID()
	}
	if o.Attempt < 1 {
		o.Attempt = 1
	}
	if o.Timestamp == "" {
		o.Timestamp = time.Now().UTC().Format(time.RFC3339Nano)
	}
	if o.Actor == "" {
		o.Actor = "system"
	}
	if o.Outcome == "" {
		o.Outcome = OutcomeFailed
	}
}

func (o Operation) Validate() error {
	if !utf8.ValidString(o.OperationID) || strings.ContainsAny(o.OperationID, `/\\`) {
		return fmt.Errorf("operation_id must be one path component")
	}
	if o.OperationID == "" {
		return fmt.Errorf("operation_id must not be empty")
	}
	for _, r := range o.OperationID {
		if unicode.IsControl(r) {
			return fmt.Errorf("operation_id must not contain control characters")
		}
	}
	if o.Attempt < 1 {
		return fmt.Errorf("attempt must be positive")
	}
	parsed, err := time.Parse(time.RFC3339Nano, o.Timestamp)
	if err != nil {
		return fmt.Errorf("timestamp must be RFC3339: %w", err)
	}
	if _, offset := parsed.Zone(); offset != 0 {
		return fmt.Errorf("timestamp must use UTC")
	}
	if o.Actor == "" {
		return fmt.Errorf("actor must not be empty")
	}
	switch o.Command {
	case CommandSeed, CommandSnap, CommandState, CommandSynth, CommandDistill, CommandWriteSummary, CommandWriteDistillation:
	default:
		return fmt.Errorf("invalid command %q", o.Command)
	}
	if o.Outcome != OutcomeCommitted && o.Outcome != OutcomeFailed {
		return fmt.Errorf("invalid outcome %q", o.Outcome)
	}
	if o.Outcome == OutcomeCommitted && o.Error != nil {
		return fmt.Errorf("committed operation must not contain an error")
	}
	if o.Outcome == OutcomeFailed && o.Error == nil {
		return fmt.Errorf("failed operation must contain an error")
	}
	if o.Error != nil {
		if !validOperationErrorKind(o.Error.Kind) {
			return fmt.Errorf("invalid error kind %q", o.Error.Kind)
		}
	}
	if o.Source != nil {
		if err := ValidateSourceKey(o.Source.SourceKey); err != nil {
			return fmt.Errorf("source: %w", err)
		}
	}
	if o.Document != nil {
		if o.Document.Kind != DocumentKindRaw && o.Document.Kind != DocumentKindSummary && o.Document.Kind != DocumentKindDistillation {
			return fmt.Errorf("document kind is invalid")
		}
		if err := ValidateDocumentName(o.Document.Filename); err != nil {
			return fmt.Errorf("document: %w", err)
		}
	}
	if o.Provenance != nil {
		if o.Provenance.DerivedFrom != nil {
			if o.Provenance.DerivedFrom.Kind != DocumentKindRaw && o.Provenance.DerivedFrom.Kind != DocumentKindSummary {
				return fmt.Errorf("provenance document kind is invalid")
			}
			if err := ValidateDocumentName(o.Provenance.DerivedFrom.Filename); err != nil {
				return fmt.Errorf("provenance: %w", err)
			}
		}
		if o.Provenance.RawWrittenAt != nil {
			if err := ValidateTimestamp(*o.Provenance.RawWrittenAt); err != nil {
				return fmt.Errorf("provenance raw_written_at: %w", err)
			}
		}
	}
	if o.Metrics != nil {
		if o.Metrics.Duration < 0 {
			return fmt.Errorf("metrics duration must not be negative")
		}
		if o.Metrics.Turns < 0 || o.Metrics.ToolCalls < 0 || o.Metrics.SummariesWritten < 0 || o.Metrics.SummariesSkipped < 0 || o.Metrics.DistillationWritten < 0 || o.Metrics.DistillationSkipped < 0 {
			return fmt.Errorf("metrics counts must not be negative")
		}
		if o.Metrics.Usage != nil && (o.Metrics.Usage.PromptTokens < 0 || o.Metrics.Usage.CompletionTokens < 0 || o.Metrics.Usage.TotalTokens < 0) {
			return fmt.Errorf("metrics usage counts must not be negative")
		}
	}
	return nil
}

func (o Operation) ValidateSeed() error {
	if err := o.Validate(); err != nil {
		return internalerrors.Wrap(internalerrors.KindValidation, "invalid seed event", err)
	}
	if o.Command != CommandSeed || o.Outcome != OutcomeCommitted || o.Error != nil {
		return internalerrors.Validation("seed event must be a committed seed without an error")
	}
	if o.Source != nil || o.Document != nil || o.Provenance != nil {
		return internalerrors.Validation("seed event must not contain source, document, or provenance")
	}
	return nil
}

func validOperationErrorKind(kind string) bool {
	switch kind {
	case "unknown", "request", "validation", "source", "filesystem", "missing_resource", "conflict", "already_exists", "provider_transport", "provider_rejected", "provider_malformed", "canceled", "deadline":
		return true
	default:
		return false
	}
}
package errors

import (
	"context"
	stderrors "errors"
	"fmt"
)

// Kind is the stable failure classification used inside bo. The root package
// exposes the public form of the same contract.
type Kind string

const (
	KindRequest           Kind = "request"
	KindValidation        Kind = "validation"
	KindSource            Kind = "source"
	KindFilesystem        Kind = "filesystem"
	KindMissingResource   Kind = "missing_resource"
	KindConflict          Kind = "conflict"
	KindAlreadyExists     Kind = "already_exists"
	KindProviderTransport Kind = "provider_transport"
	KindProviderRejected  Kind = "provider_rejected"
	KindProviderMalformed Kind = "provider_malformed"
	KindCanceled          Kind = "canceled"
	KindDeadline          Kind = "deadline"
)

// Error is the internal form of bo's stable failure contract.
type Error struct {
	Kind      Kind
	Detail    string
	Retryable bool
	Cause     error
}

func (e *Error) Error() string {
	if e == nil {
		return "<nil>"
	}
	if e.Detail == "" {
		return string(e.Kind)
	}
	return fmt.Sprintf("%s: %s", e.Kind, e.Detail)
}

func (e *Error) Unwrap() error {
	if e == nil {
		return nil
	}
	return e.Cause
}

func New(kind Kind, detail string) *Error { return &Error{Kind: kind, Detail: detail} }

func Wrap(kind Kind, detail string, cause error) *Error {
	return &Error{Kind: kind, Detail: detail, Cause: cause}
}

func Request(detail string) *Error         { return New(KindRequest, detail) }
func Validation(detail string) *Error      { return New(KindValidation, detail) }
func Source(detail string) *Error          { return New(KindSource, detail) }
func Filesystem(detail string) *Error      { return New(KindFilesystem, detail) }
func MissingResource(detail string) *Error { return New(KindMissingResource, detail) }
func Conflict(detail string) *Error        { return New(KindConflict, detail) }
func AlreadyExists(detail string) *Error   { return New(KindAlreadyExists, detail) }

func ProviderTransport(detail string, cause error) *Error {
	return Wrap(KindProviderTransport, detail, cause)
}

func TransientProviderTransport(detail string, cause error) *Error {
	err := ProviderTransport(detail, cause)
	err.Retryable = true
	return err
}

func ProviderRejected(detail string, retryable bool) *Error {
	err := New(KindProviderRejected, detail)
	err.Retryable = retryable
	return err
}

func ProviderMalformed(detail string, cause error) *Error {
	return Wrap(KindProviderMalformed, detail, cause)
}

func Context(err error) *Error {
	if err == nil {
		return nil
	}
	var categorized *Error
	if stderrors.As(err, &categorized) {
		if categorized.Kind == KindCanceled || categorized.Kind == KindDeadline {
			return categorized
		}
		return nil
	}
	if stderrors.Is(err, context.Canceled) {
		return Wrap(KindCanceled, "operation canceled", err)
	}
	if stderrors.Is(err, context.DeadlineExceeded) {
		return Wrap(KindDeadline, "operation deadline exceeded", err)
	}
	return nil
}

var ErrAlreadyExists = stderrors.New("document already exists")

func IsKind(err error, kind Kind) bool {
	var categorized *Error
	return stderrors.As(err, &categorized) && categorized.Kind == kind
}

func IsAlreadyExists(err error) bool {
	return stderrors.Is(err, ErrAlreadyExists) || IsKind(err, KindAlreadyExists)
}

