func synthProvider(name string) (bo.Provider, error) {
	switch name {
	case "deepseek":
		apiKey := os.Getenv("DEEPSEEK_API_KEY")
		if apiKey == "" {
			return bo.Provider{}, fmt.Errorf("DEEPSEEK_API_KEY is not set")
		}
		return bo.NewDeepSeekProvider(bo.DeepSeekConfig{APIKey: apiKey, Endpoint: os.Getenv("DEEPSEEK_API_URL"), Model: os.Getenv("DEEPSEEK_MODEL")}), nil
	case "gemini":
		apiKey := geminiAPIKey()
		if apiKey == "" {
			return bo.Provider{}, fmt.Errorf("GEMINI_API_KEY or GOOGLE_API_KEY is not set")
		}
		thinkingBudget, err := geminiThinkingBudget()
		if err != nil {
			return bo.Provider{}, err
		}
		return bo.NewGeminiProvider(bo.GeminiConfig{APIKey: apiKey, Endpoint: os.Getenv("GEMINI_API_URL"), Model: os.Getenv("GEMINI_MODEL"), ThinkingBudget: thinkingBudget}), nil
	case "vertex":
		projectID := os.Getenv("GOOGLE_CLOUD_PROJECT")
		location := os.Getenv("GOOGLE_CLOUD_LOCATION")
		if projectID == "" || location == "" {
			return bo.Provider{}, fmt.Errorf("GOOGLE_CLOUD_PROJECT and GOOGLE_CLOUD_LOCATION are required for vertex")
		}
		thinkingBudget, err := geminiThinkingBudget()
		if err != nil {
			return bo.Provider{}, err
		}
		return bo.NewVertexGeminiProvider(context.Background(), bo.GeminiConfig{
			ProjectID: projectID, Location: location, Endpoint: os.Getenv("GEMINI_API_URL"), Model: os.Getenv("GEMINI_MODEL"), ThinkingBudget: thinkingBudget,
		})
	default:
		return bo.Provider{}, fmt.Errorf("%s", synthUsage())
	}
}

func geminiAPIKey() string {
	if key := os.Getenv("GEMINI_API_KEY"); key != "" {
		return key
	}
	return os.Getenv("GOOGLE_API_KEY")
}

func geminiThinkingBudget() (*int, error) {
	value := os.Getenv("GEMINI_THINKING_BUDGET")
	if value == "" {
		return nil, nil
	}
	budget, err := strconv.Atoi(value)
	if err != nil || budget < -1 {
		return nil, fmt.Errorf("GEMINI_THINKING_BUDGET must be -1 or a non-negative integer")
	}
	return &budget, nil
}

func printSynthReport(result bo.SynthResult) {
	if len(result.Report) == 0 {
		fmt.Println("no committed actions")
		return
	}
	for _, operation := range result.Report {
		fmt.Printf("%s:\n", operation.Operation)
		for _, document := range operation.Documents {
			fmt.Printf("  - %s\n", document.Filename)
		}
	}
}

func addSeedHint(err error, name string) error {
	if !bo.IsKind(err, bo.ErrorKindMissingResource) {
		return err
	}
	return fmt.Errorf("%w (run bo seed --name %s)", err, name)
}

func printSnapReport(result bo.SnapResult, fatal error) bool {
	total := len(result.Outcomes)
	failed := 0
	for _, outcome := range result.Outcomes {
		if outcome.Err != nil {
			failed++
			fmt.Fprintf(os.Stderr, "failed: %s (%v)\n", outcome.SourceKey, outcome.Err)
		} else {
			fmt.Printf("snapped: %s -> %s\n", outcome.SourceKey, outcome.Filename)
		}
	}
	aborted := result.Aborted || fatal != nil
	if fatal != nil {
		if result.FailedSource != "" {
			fmt.Fprintf(os.Stderr, "failed: %s (%v)\n", result.FailedSource, fatal)
		} else {
			fmt.Fprintf(os.Stderr, "snap failed: %v\n", fatal)
		}
	}
	totalFailed := failed
	if aborted {
		totalFailed++
	}
	if aborted {
		fmt.Fprintf(os.Stderr, "%d succeeded / %d failed; batch aborted\n", total-failed, totalFailed)
	} else {
		fmt.Fprintf(os.Stderr, "%d succeeded / %d failed\n", total-failed, totalFailed)
	}
	return aborted || failed > 0
}

func fail(operation, detail string) {
	fmt.Fprintf(os.Stderr, "%s failed: %s\n", operation, detail)
	os.Exit(1)
}
package main

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/skillicinski/bo"
)

func synthUsage() string {
	return "usage: bo synth <name> [summarize|distill] [--provider deepseek|gemini|vertex] [--max-turns N] [--max-tool-calls N] [--max-tool-output-bytes N] [--max-response-tokens N] [--timeout-seconds N]"
}

func parseSynthOptions(args []string) (bo.SynthesisOptions, error) {
	return parseAgentOptions(args, synthUsage())
}

func parseSynthMode(args []string) (bo.SynthMode, []string, error) {
	if len(args) == 0 || strings.HasPrefix(args[0], "-") {
		return bo.SynthModeDefault, args, nil
	}
	switch args[0] {
	case "summarize":
		return bo.SynthModeSummarize, args[1:], nil
	case "distill":
		return bo.SynthModeDistill, args[1:], nil
	default:
		return bo.SynthModeDefault, nil, fmt.Errorf("%s", synthUsage())
	}
}

func parseSynthProvider(args []string) (string, []string, error) {
	provider := "deepseek"
	remaining := make([]string, 0, len(args))
	for index := 0; index < len(args); index++ {
		if args[index] != "--provider" {
			remaining = append(remaining, args[index])
			continue
		}
		if index+1 >= len(args) {
			return "", nil, fmt.Errorf("missing value for --provider")
		}
		provider = args[index+1]
		index++
		switch provider {
		case "deepseek", "gemini", "vertex":
		default:
			return "", nil, fmt.Errorf("%s", synthUsage())
		}
	}
	return provider, remaining, nil
}

func parseAgentOptions(args []string, usage string) (bo.SynthesisOptions, error) {
	config := bo.DefaultSynthesisOptions()
	for index := 0; index < len(args); index++ {
		option := args[index]
		switch option {
		case "--max-turns", "--max-tool-calls", "--max-tool-output-bytes", "--max-response-tokens", "--timeout-seconds":
		default:
			return bo.SynthesisOptions{}, fmt.Errorf("%s", usage)
		}
		if index+1 >= len(args) {
			return bo.SynthesisOptions{}, fmt.Errorf("missing value for %s", option)
		}
		value := args[index+1]
		index++
		number, err := strconv.Atoi(value)
		if err != nil || number <= 0 {
			return bo.SynthesisOptions{}, fmt.Errorf("%s requires a positive integer", option)
		}
		switch option {
		case "--max-turns":
			config.MaxTurns = number
		case "--max-tool-calls":
			config.MaxToolCalls = number
