const MaxSourceBytes = 10 << 20

var ErrNotHandled = errors.New("source not handled")

func ReadAll(reader io.Reader) ([]byte, error) {
	data, err := io.ReadAll(io.LimitReader(reader, MaxSourceBytes+1))
	if err != nil {
		return nil, err
	}
	if len(data) > MaxSourceBytes {
		return nil, internalerrors.Source(fmt.Sprintf("source exceeds %d-byte limit", MaxSourceBytes))
	}
	return data, nil
}

type OriginType string

const (
	OriginHTML     OriginType = "html"
	OriginYouTube  OriginType = "youtube"
	OriginMarkdown OriginType = "markdown"
)

type Origin struct {
	Type      OriginType
	SourceKey string
	Value     string
}

func NewOrigin(kind OriginType, sourceKey, value string) Origin {
	return Origin{Type: kind, SourceKey: sourceKey, Value: value}
}

type Transport interface {
	Route(context.Context, string) (Origin, error)
}

type Plugin interface {
	Handle(context.Context, Origin) (domain.RawSnapshot, error)
}

type Fetcher interface {
	Fetch(context.Context, string) (domain.RawSnapshot, error)
}

type Workflow struct {
	transports []Transport
	plugins    map[OriginType]Plugin
}

func NewWorkflow(transports []Transport, plugins map[OriginType]Plugin) *Workflow {
	registered := make(map[OriginType]Plugin, len(plugins))
	for kind, plugin := range plugins {
		registered[kind] = plugin
	}
	return &Workflow{transports: append([]Transport(nil), transports...), plugins: registered}
}

func (w *Workflow) Fetch(ctx context.Context, input string) (domain.RawSnapshot, error) {
	if w == nil {
		return domain.RawSnapshot{}, internalerrors.Request("source workflow is not configured")
	}
	if err := ctx.Err(); err != nil {
		return domain.RawSnapshot{}, internalerrors.Context(err)
	}
	for _, transport := range w.transports {
		origin, err := transport.Route(ctx, input)
		if errors.Is(err, ErrNotHandled) {
			continue
		}
		if err != nil {
			return domain.RawSnapshot{}, normalizeError(err, "routing source")
		}
		kind := origin.Type
		plugin, ok := w.plugins[kind]
		if !ok || plugin == nil {
			return domain.RawSnapshot{}, internalerrors.Source(fmt.Sprintf("no plugin for source type %q", kind))
		}
		snapshot, err := plugin.Handle(ctx, origin)
		if err != nil {
			return domain.RawSnapshot{}, normalizeError(err, "handling source")
		}
		if snapshot.SourceKey == "" {
			snapshot.SourceKey = origin.SourceKey
		}
		return snapshot, nil
	}
	return domain.RawSnapshot{}, internalerrors.Source("input is not a supported source")
}

func normalizeError(err error, detail string) error {
	if err == nil {
		return nil
	}
	var categorized *internalerrors.Error
	if errors.As(err, &categorized) {
		return err
	}
	if contextErr := internalerrors.Context(err); contextErr != nil {
		return contextErr
	}
	return internalerrors.Wrap(internalerrors.KindSource, detail, err)
}
package file

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
	"github.com/skillicinski/bo/internal/source"
)

type Transport struct{}

func NewTransport() *Transport { return &Transport{} }

func (t *Transport) Route(_ context.Context, input string) (source.Origin, error) {
	extension := filepath.Ext(input)
	if !strings.EqualFold(extension, ".md") {
		if extension != "" {
			return source.Origin{}, internalerrors.Source("file extension must be .md")
		}
		return source.Origin{}, source.ErrNotHandled
	}
	filename := filepath.Base(input)
	return source.NewOrigin(source.OriginMarkdown, "raw:"+filename, input), nil
}

type MarkdownPlugin struct{}

func NewMarkdownPlugin() *MarkdownPlugin { return &MarkdownPlugin{} }

func (p *MarkdownPlugin) Handle(ctx context.Context, origin source.Origin) (domain.RawSnapshot, error) {
	if err := ctx.Err(); err != nil {
		return domain.RawSnapshot{}, internalerrors.Context(err)
	}
	file, err := os.Open(origin.Value)
	if err != nil {
		kind := internalerrors.KindFilesystem
		if errors.Is(err, os.ErrNotExist) {
			kind = internalerrors.KindMissingResource
		}
		return domain.RawSnapshot{}, internalerrors.Wrap(kind, fmt.Sprintf("reading %s failed", origin.Value), err)
	}
	defer file.Close()
	data, err := source.ReadAll(file)
	if err != nil {
		if internalerrors.IsKind(err, internalerrors.KindSource) {
			return domain.RawSnapshot{}, err
		}
		return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindFilesystem, fmt.Sprintf("reading %s failed", origin.Value), err)
	}
	if len(strings.TrimSpace(string(data))) == 0 {
		return domain.RawSnapshot{}, internalerrors.Source("Markdown file is empty")
	}
	title := markdownTitle(data, filepath.Base(origin.Value))
	return domain.NewRawSnapshot(origin.SourceKey, title, data), nil
}

func markdownTitle(data []byte, filename string) string {
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "# ") {
			if title := strings.TrimSpace(strings.TrimPrefix(line, "# ")); title != "" {
				return title
			}
		}
	}
	return strings.TrimSuffix(filename, filepath.Ext(filename))
}
package url

import (
	"context"
	"net/http"
	"net/url"
	"strings"

	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
	"github.com/skillicinski/bo/internal/source"
)

const DefaultUserAgent = "bo/0.1"

type Requester interface {
	Do(*http.Request) (*http.Response, error)
}

type Transport struct{}

func NewTransport() *Transport { return &Transport{} }

func sourceFailure(detail string, err error) error {
	if contextErr := internalerrors.Context(err); contextErr != nil {
		return contextErr
	}
	return internalerrors.Wrap(internalerrors.KindSource, detail, err)
}

func (t *Transport) Route(ctx context.Context, input string) (source.Origin, error) {
	if err := ctx.Err(); err != nil {
		return source.Origin{}, internalerrors.Context(err)
	}
	parsed, err := url.Parse(input)
	if err != nil {
		if strings.Contains(input, "://") || strings.HasPrefix(input, "http:") || strings.HasPrefix(input, "https:") {
			return source.Origin{}, internalerrors.Wrap(internalerrors.KindValidation, "invalid URL", err)
		}
		return source.Origin{}, source.ErrNotHandled
	}
	if (parsed.Scheme == "http" || parsed.Scheme == "https") && (parsed.Fragment != "" || strings.Contains(input, "#")) {
		return source.Origin{}, internalerrors.Validation("URL must not contain a fragment")
	}
	match := ClassifyYouTubeURL(input)
	if parsed.Scheme == "http" || parsed.Scheme == "https" {
		if parsed.Host == "" {
			return source.Origin{}, internalerrors.Validation("URL must include a host")
		}
		if err := domain.ValidateSourceKey(input); err != nil {
			return source.Origin{}, err
		}
	}
	if match.Kind == YouTubeSupported {
		return source.NewOrigin(source.OriginYouTube, input, input), nil
	}
	if match.Kind == YouTubeUnsupported {
		return source.Origin{}, internalerrors.Source("YouTube URL: " + match.Reason)
	}
	if parsed.Scheme == "" {
		return source.Origin{}, source.ErrNotHandled
	}
	if parsed.Scheme != "http" && parsed.Scheme != "https" {
		return source.Origin{}, internalerrors.Validation("URL scheme must be http or https")
	}
	if parsed.Host == "" {
		return source.Origin{}, internalerrors.Validation("URL must include a host")
	}
	return source.NewOrigin(source.OriginHTML, input, parsed.String()), nil
}
package url

import (
	"bytes"
	"context"
	"fmt"
	"net/http"
	"strings"
	"unicode"

	htmltomarkdown "github.com/JohannesKaufmann/html-to-markdown/v2"
	"golang.org/x/net/html"

	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
	"github.com/skillicinski/bo/internal/source"
)

type HTMLPlugin struct {
	Client    Requester
	UserAgent string
}

func NewHTML(client Requester) *HTMLPlugin {
	return &HTMLPlugin{Client: client, UserAgent: DefaultUserAgent}
}

func (p *HTMLPlugin) Handle(ctx context.Context, origin source.Origin) (domain.RawSnapshot, error) {
	client := p.client()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, origin.Value, nil)
	if err != nil {
		return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindValidation, "invalid URL", err)
	}
	request.Header.Set("User-Agent", p.userAgent())
	response, err := client.Do(request)
	if err != nil {
		return domain.RawSnapshot{}, sourceFailure("request failed", err)
	}
	defer response.Body.Close()
	if response.StatusCode < 200 || response.StatusCode >= 300 {
		return domain.RawSnapshot{}, internalerrors.Source(fmt.Sprintf("source returned HTTP %d", response.StatusCode))
	}
	contentType := response.Header.Get("Content-Type")
	if !isHTMLContentType(contentType) {
		return domain.RawSnapshot{}, internalerrors.Source(fmt.Sprintf("not HTML (Content-Type: %s)", contentType))
	}
	body, err := source.ReadAll(response.Body)
	if err != nil {
		return domain.RawSnapshot{}, sourceFailure("reading response failed", err)
	}
	snapshot, err := ExtractHTML(string(body))
	if err != nil {
		return domain.RawSnapshot{}, err
	}
	snapshot.SourceKey = origin.SourceKey
	return snapshot, nil
}

func (p *HTMLPlugin) client() Requester {
	if p == nil || p.Client == nil {
		return http.DefaultClient
	}
	return p.Client
}

func (p *HTMLPlugin) userAgent() string {
	if p == nil || p.UserAgent == "" {
		return DefaultUserAgent
	}
	return p.UserAgent
}

func isHTMLContentType(value string) bool {
	mediaType := strings.ToLower(strings.TrimSpace(strings.SplitN(value, ";", 2)[0]))
	return mediaType == "text/html" || mediaType == "application/xhtml+xml"
}

var skippedTags = map[string]bool{
	"aside": true, "footer": true, "form": true, "header": true, "nav": true,
	"noscript": true, "script": true, "style": true, "svg": true, "template": true,
}

func ExtractHTML(input string) (domain.RawSnapshot, error) {
	document, err := html.Parse(strings.NewReader(input))
	if err != nil {
		return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindSource, "HTML parsing failed", err)
	}
	title := strings.Join(strings.Fields(textContent(findElement(document, "title"))), " ")
	if title == "" {
		return domain.RawSnapshot{}, internalerrors.Source("page has no title")
	}
	removeSkipped(document)
	for _, tag := range []string{"article", "main", "body"} {
		element := findElement(document, tag)
		if element == nil {
			continue
		}
		var rendered bytes.Buffer
		if err := html.Render(&rendered, element); err != nil {
			return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindSource, "HTML rendering failed", err)
		}
		markdown, err := htmltomarkdown.ConvertString(rendered.String())
		if err != nil {
			return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindSource, "HTML conversion failed", err)
		}
		markdown = removeMatchingTitleHeading(markdown, title)
		if hasAlphaNumeric(markdown) {
			return domain.NewRawSnapshot("", title, []byte(fmt.Sprintf("# %s\n\n%s\n", title, strings.TrimSpace(markdown)))), nil
		}
	}
	return domain.RawSnapshot{}, internalerrors.Source("page has no readable content")
}

func findElement(node *html.Node, wanted string) *html.Node {
	if node.Type == html.ElementNode && node.Data == wanted {
		return node
	}
	for child := node.FirstChild; child != nil; child = child.NextSibling {
		if found := findElement(child, wanted); found != nil {
			return found
		}
	}
	return nil
}

func textContent(node *html.Node) string {
	if node == nil {
		return ""
	}
	if node.Type == html.TextNode {
		return node.Data
	}
	var builder strings.Builder
	for child := node.FirstChild; child != nil; child = child.NextSibling {
		builder.WriteString(textContent(child))
	}
	return builder.String()
}

func removeSkipped(node *html.Node) {
	for child := node.FirstChild; child != nil; {
		next := child.NextSibling
		if child.Type == html.ElementNode && skippedTags[child.Data] {
			node.RemoveChild(child)
		} else {
			removeSkipped(child)
		}
		child = next
	}
}

func removeMatchingTitleHeading(markdown, title string) string {
	lines := strings.Split(markdown, "\n")
	if len(lines) == 0 {
		return ""
	}
	if strings.HasPrefix(lines[0], "# ") && strings.EqualFold(strings.TrimSpace(strings.TrimPrefix(lines[0], "# ")), strings.TrimSpace(title)) {
		lines = lines[1:]
	}
	return strings.TrimSpace(strings.Join(lines, "\n"))
}

func hasAlphaNumeric(value string) bool {
	for _, r := range value {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			return true
		}
	}
	return false
}

