package agent

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"fmt"
	"strings"
	"time"
	"unicode/utf8"

	internalerrors "github.com/skillicinski/bo/internal/errors"
)

const (
	DefaultMaxTurns           = 32
	DefaultMaxToolCalls       = 64
	DefaultMaxToolOutputBytes = 65_536
	DefaultMaxResponseTokens  = 4_096
)

type Options struct {
	MaxTurns           int
	MaxToolCalls       int
	MaxToolOutputBytes int
	MaxResponseTokens  int
}

func DefaultOptions() Options {
	return Options{
		MaxTurns: DefaultMaxTurns, MaxToolCalls: DefaultMaxToolCalls,
		MaxToolOutputBytes: DefaultMaxToolOutputBytes, MaxResponseTokens: DefaultMaxResponseTokens,
	}
}

type ChatMessage struct {
	Role       string
	Content    any
	Name       string
	ToolCalls  []ToolCall
	ToolCallID string
	// ProviderMetadata is immutable provider-owned state for message replay.
	ProviderMetadata string
}

type ToolCall struct {
	ID       string
	Function ToolFunction
}

type ToolFunction struct {
	Name      string
	Arguments string
}

type ToolDefinition struct {
	Function ToolDeclaration
}

type ToolDeclaration struct {
	Name        string
	Description string
	Parameters  map[string]any
}

type CompletionRequest struct {
	Messages  []ChatMessage
	Tools     []ToolDefinition
	MaxTokens int
}

type CompletionResponse struct {
	Message              ChatMessage
	Usage                *TokenUsage
	ProviderRetries      int
	ProviderRetryReasons []string
}

type TokenUsage struct {
	PromptTokens     int `json:"prompt_tokens"`
	CompletionTokens int `json:"completion_tokens"`
	TotalTokens      int `json:"total_tokens"`
	ThoughtsTokens   int `json:"thoughts_tokens,omitempty"`
}

type CompletionProvider interface {
	Complete(context.Context, CompletionRequest) (CompletionResponse, error)
}

type Tool struct {
	Definition ToolDefinition
	Execute    func(context.Context, ToolCall) (string, error)
}

type Runtime struct {
	Provider CompletionProvider
	Tools    []Tool
	Done     func() bool
}

type Metrics struct {
	Turns     int           `json:"turns"`
	ToolCalls int           `json:"tool_calls"`
	Usage     *TokenUsage   `json:"usage,omitempty"`
	Duration  time.Duration `json:"duration"`
}

// ToolCallTelemetry records bounded metadata for one provider-requested tool call.
// ArgumentsPreview is populated only for read and terminal tools.
type ToolCallTelemetry struct {
	Turn                int    `json:"turn"`
	Index               int    `json:"index"`
	ID                  string `json:"id,omitempty"`
	Name                string `json:"name"`
	ArgumentsBytes      int    `json:"arguments_bytes"`
	ArgumentsSHA256     string `json:"arguments_sha256"`
	ArgumentsPreview    string `json:"arguments_preview,omitempty"`
	OutputBytes         int    `json:"output_bytes"`
	OutputReturnedBytes int    `json:"output_returned_bytes"`
	OutputSHA256        string `json:"output_sha256"`
	OutputTruncated     bool   `json:"output_truncated,omitempty"`
	Error               string `json:"error,omitempty"`
}

type Telemetry struct {
	ToolCalls            []ToolCallTelemetry `json:"tool_calls,omitempty"`
	ProviderRetries      int                 `json:"provider_retries,omitempty"`
	ProviderRetryReasons []string            `json:"provider_retry_reasons,omitempty"`
	TerminalReason       string              `json:"terminal_reason,omitempty"`
}

type Result struct {
	Messages []ChatMessage
	Message  ChatMessage
	Metrics
	Telemetry Telemetry
}

func (runtime Runtime) Run(ctx context.Context, messages []ChatMessage, options Options) (Result, error) {
	started := time.Now()
	turns, toolCalls := 0, 0
	telemetry := Telemetry{}
	var usage TokenUsage
	usageKnown := true
	usageReceived := false
	finish := func(reason string, message ChatMessage, err error) (Result, error) {
		metrics := Metrics{Turns: turns, ToolCalls: toolCalls, Duration: time.Since(started)}
		if usageKnown && usageReceived && turns > 0 {
			metrics.Usage = &usage
		}
		telemetry.TerminalReason = reason
		return Result{Messages: messages, Message: message, Metrics: metrics, Telemetry: telemetry}, err
	}
	if runtime.Provider == nil {
		return finish("provider_not_configured", ChatMessage{}, internalerrors.Request("agent provider is not configured"))
	}
	options = normalizedOptions(options)
	var lastToolError error
	terminalError := func(fallback, batchError error) error {
		if batchError != nil {
			return batchError
		}
		if lastToolError != nil {
			return lastToolError
		}
		return fallback
	}
	definitions := make([]ToolDefinition, 0, len(runtime.Tools))
	executors := make(map[string]func(context.Context, ToolCall) (string, error), len(runtime.Tools))
	for _, tool := range runtime.Tools {
		name := tool.Definition.Function.Name
		definitions = append(definitions, tool.Definition)
		executors[name] = tool.Execute
	}
	for {
		if err := ctx.Err(); err != nil {
			return finish("context_error", ChatMessage{}, internalerrors.Context(err))
		}
		if turns >= options.MaxTurns {
			return finish("max_turns", ChatMessage{}, terminalError(internalerrors.ProviderMalformed(fmt.Sprintf("max turns reached (%d)", options.MaxTurns), nil), nil))
		}
		turns++
		response, err := runtime.Provider.Complete(ctx, CompletionRequest{
			Messages: messages, Tools: definitions, MaxTokens: options.MaxResponseTokens,
		})
		if response.Usage != nil && usageKnown {
			usage.PromptTokens += response.Usage.PromptTokens
			usage.CompletionTokens += response.Usage.CompletionTokens
			usage.TotalTokens += response.Usage.TotalTokens
			usage.ThoughtsTokens += response.Usage.ThoughtsTokens
			usageReceived = true
		} else if err == nil {
			usageKnown = false
		}
		if response.ProviderRetries > 0 {
			telemetry.ProviderRetries += response.ProviderRetries
		}
		if len(response.ProviderRetryReasons) > 0 {
			telemetry.ProviderRetryReasons = append(telemetry.ProviderRetryReasons, response.ProviderRetryReasons...)
		}
		if err != nil {
			return finish("provider_error", ChatMessage{}, providerError(err))
		}
		message := response.Message
		if message.Role == "" {
			message.Role = "assistant"
		}
		if len(message.ToolCalls) > 0 {
			messages = append(messages, message)
			batchToolError := error(nil)
			for _, call := range message.ToolCalls {
				if toolCalls >= options.MaxToolCalls {
					return finish("max_tool_calls", message, terminalError(internalerrors.ProviderMalformed(fmt.Sprintf("max tool calls reached (%d)", options.MaxToolCalls), nil), batchToolError))
				}
				toolCalls++
				telemetry.ToolCalls = append(telemetry.ToolCalls, ToolCallTelemetry{
					Turn: turns, Index: toolCalls, ID: call.ID, Name: call.Function.Name,
					ArgumentsBytes: len(call.Function.Arguments), ArgumentsSHA256: sha256Hex(call.Function.Arguments),
					ArgumentsPreview: toolArgumentsPreview(call.Function.Name, call.Function.Arguments),
				})
				trace := &telemetry.ToolCalls[len(telemetry.ToolCalls)-1]
				if call.ID == "" {
					trace.Error = "assistant tool call has no id"
					return finish("invalid_tool_call", message, internalerrors.ProviderMalformed("assistant tool call has no id", nil))
				}
				execute, ok := executors[call.Function.Name]
				var output string
				var toolErr error
				if !ok {
					toolErr = fmt.Errorf("unsupported tool: %s", call.Function.Name)
				} else if execute == nil {
					toolErr = fmt.Errorf("tool is not configured: %s", call.Function.Name)
				} else {
					output, toolErr = execute(ctx, call)
				}
				if toolErr != nil {
					trace.Error = toolErr.Error()
					var categorized *internalerrors.Error
					if errors.As(toolErr, &categorized) {
						batchToolError = toolErr
					}
					output = "ERROR: " + toolErr.Error()
				}
				boundedOutput := BoundedOutput(output, options.MaxToolOutputBytes)
				trace.OutputBytes = len(output)
				trace.OutputReturnedBytes = len(boundedOutput)
				trace.OutputSHA256 = sha256Hex(output)
				trace.OutputTruncated = len(output) != len(boundedOutput)
				messages = append(messages, ChatMessage{Role: "tool", ToolCallID: call.ID, Content: boundedOutput})
			}
			lastToolError = batchToolError
			if runtime.Done != nil && runtime.Done() {
				reason := "done"
				if lastToolError != nil {
					reason = "done_with_tool_error"
				}
				return finish(reason, message, lastToolError)
			}
			continue
		}
		messages = append(messages, message)
		reason := "assistant_message"
		if lastToolError != nil {
			reason = "assistant_message_with_tool_error"
		}
		return finish(reason, message, lastToolError)
	}
}

func sha256Hex(value string) string {
	digest := sha256.Sum256([]byte(value))
	return hex.EncodeToString(digest[:])
}

func toolArgumentsPreview(name, arguments string) string {
	if strings.HasPrefix(name, "read_") || name == "skip_distill" {
		return BoundedOutput(arguments, 2048)
	}
	return ""
}

func providerError(err error) error {
	var categorized *internalerrors.Error
	if errors.As(err, &categorized) {
		return err
	}
	if contextErr := internalerrors.Context(err); contextErr != nil {
		return contextErr
	}
	return internalerrors.ProviderTransport(err.Error(), err)
}

func normalizedOptions(options Options) Options {
	defaults := DefaultOptions()
	if options.MaxTurns <= 0 {
		options.MaxTurns = defaults.MaxTurns
	}
	if options.MaxToolCalls <= 0 {
		options.MaxToolCalls = defaults.MaxToolCalls
	}
	if options.MaxToolOutputBytes <= 0 {
		options.MaxToolOutputBytes = defaults.MaxToolOutputBytes
	}
	if options.MaxResponseTokens <= 0 {
		options.MaxResponseTokens = defaults.MaxResponseTokens
	}
	return options
}

func BoundedOutput(value string, limit int) string {
	if len(value) <= limit {
		return value
	}
	marker := fmt.Sprintf("\n[truncated at %d bytes]\n", len(value))
	if len(marker) >= limit {
		return takePrefix(marker, limit)
	}
	return takePrefix(value, limit-len(marker)) + marker
}

func takePrefix(value string, limit int) string {
	if limit >= len(value) {
		return value
	}
	if limit <= 0 {
		return ""
	}
	for limit > 0 && !utf8.RuneStart(value[limit]) {
		limit--
	}
	return value[:limit]
}
package source

import (
	"context"
	"errors"
	"fmt"
	"io"

	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
)

const MaxSourceBytes = 10 << 20

var ErrNotHandled = errors.New("source not handled")

func ReadAll(reader io.Reader) ([]byte, error) {
	data, err := io.ReadAll(io.LimitReader(reader, MaxSourceBytes+1))
	if err != nil {
		return nil, err
	}
	if len(data) > MaxSourceBytes {
		return nil, internalerrors.Source(fmt.Sprintf("source exceeds %d-byte limit", MaxSourceBytes))
	}
	return data, nil
}

type OriginType string

const (
	OriginHTML     OriginType = "html"
	OriginYouTube  OriginType = "youtube"
	OriginMarkdown OriginType = "markdown"
)

type Origin struct {
	Type      OriginType
	SourceKey string
	Value     string
}

func NewOrigin(kind OriginType, sourceKey, value string) Origin {
	return Origin{Type: kind, SourceKey: sourceKey, Value: value}
}

type Transport interface {
	Route(context.Context, string) (Origin, error)
}

type Plugin interface {
	Handle(context.Context, Origin) (domain.RawSnapshot, error)
}

type Fetcher interface {
	Fetch(context.Context, string) (domain.RawSnapshot, error)
}

type Workflow struct {
	transports []Transport
	plugins    map[OriginType]Plugin
}

func NewWorkflow(transports []Transport, plugins map[OriginType]Plugin) *Workflow {
	registered := make(map[OriginType]Plugin, len(plugins))
	for kind, plugin := range plugins {
		registered[kind] = plugin
	}
	return &Workflow{transports: append([]Transport(nil), transports...), plugins: registered}
}

func (w *Workflow) Fetch(ctx context.Context, input string) (domain.RawSnapshot, error) {
	if w == nil {
		return domain.RawSnapshot{}, internalerrors.Request("source workflow is not configured")
	}
	if err := ctx.Err(); err != nil {
		return domain.RawSnapshot{}, internalerrors.Context(err)
	}
	for _, transport := range w.transports {
		origin, err := transport.Route(ctx, input)
		if errors.Is(err, ErrNotHandled) {
			continue
		}
		if err != nil {
			return domain.RawSnapshot{}, normalizeError(err, "routing source")
		}
		kind := origin.Type
		plugin, ok := w.plugins[kind]
		if !ok || plugin == nil {
			return domain.RawSnapshot{}, internalerrors.Source(fmt.Sprintf("no plugin for source type %q", kind))
		}
		snapshot, err := plugin.Handle(ctx, origin)
		if err != nil {
			return domain.RawSnapshot{}, normalizeError(err, "handling source")
		}
		if snapshot.SourceKey == "" {
			snapshot.SourceKey = origin.SourceKey
		}
		return snapshot, nil
	}
	return domain.RawSnapshot{}, internalerrors.Source("input is not a supported source")
}

func normalizeError(err error, detail string) error {
	if err == nil {
		return nil
	}
	var categorized *internalerrors.Error
	if errors.As(err, &categorized) {
		return err
	}
	if contextErr := internalerrors.Context(err); contextErr != nil {
		return contextErr
	}
	return internalerrors.Wrap(internalerrors.KindSource, detail, err)
}
package file

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
	"github.com/skillicinski/bo/internal/source"
)

type Transport struct{}

func NewTransport() *Transport { return &Transport{} }

func (t *Transport) Route(_ context.Context, input string) (source.Origin, error) {
	extension := filepath.Ext(input)
	if !strings.EqualFold(extension, ".md") {
		if extension != "" {
			return source.Origin{}, internalerrors.Source("file extension must be .md")
		}
		return source.Origin{}, source.ErrNotHandled
	}
	filename := filepath.Base(input)
	return source.NewOrigin(source.OriginMarkdown, "raw:"+filename, input), nil
}

type MarkdownPlugin struct{}

func NewMarkdownPlugin() *MarkdownPlugin { return &MarkdownPlugin{} }

func (p *MarkdownPlugin) Handle(ctx context.Context, origin source.Origin) (domain.RawSnapshot, error) {
	if err := ctx.Err(); err != nil {
		return domain.RawSnapshot{}, internalerrors.Context(err)
	}
	file, err := os.Open(origin.Value)
	if err != nil {
		kind := internalerrors.KindFilesystem
		if errors.Is(err, os.ErrNotExist) {
			kind = internalerrors.KindMissingResource
		}
		return domain.RawSnapshot{}, internalerrors.Wrap(kind, fmt.Sprintf("reading %s failed", origin.Value), err)
	}
	defer file.Close()
	data, err := source.ReadAll(file)
	if err != nil {
		if internalerrors.IsKind(err, internalerrors.KindSource) {
			return domain.RawSnapshot{}, err
		}
		return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindFilesystem, fmt.Sprintf("reading %s failed", origin.Value), err)
	}
	if len(strings.TrimSpace(string(data))) == 0 {
		return domain.RawSnapshot{}, internalerrors.Source("Markdown file is empty")
	}
	title := markdownTitle(data, filepath.Base(origin.Value))
	return domain.NewRawSnapshot(origin.SourceKey, title, data), nil
}

func markdownTitle(data []byte, filename string) string {
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "# ") {
			if title := strings.TrimSpace(strings.TrimPrefix(line, "# ")); title != "" {
				return title
			}
		}
	}
	return strings.TrimSuffix(filename, filepath.Ext(filename))
}
package url

import (
	"context"
	"net/http"
	"net/url"
	"strings"

	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
	"github.com/skillicinski/bo/internal/source"
)

const DefaultUserAgent = "bo/0.1"

type Requester interface {
	Do(*http.Request) (*http.Response, error)
}

type Transport struct{}

func NewTransport() *Transport { return &Transport{} }

func sourceFailure(detail string, err error) error {
	if contextErr := internalerrors.Context(err); contextErr != nil {
		return contextErr
	}
	return internalerrors.Wrap(internalerrors.KindSource, detail, err)
}

func (t *Transport) Route(ctx context.Context, input string) (source.Origin, error) {
	if err := ctx.Err(); err != nil {
		return source.Origin{}, internalerrors.Context(err)
	}
	parsed, err := url.Parse(input)
	if err != nil {
		if strings.Contains(input, "://") || strings.HasPrefix(input, "http:") || strings.HasPrefix(input, "https:") {
			return source.Origin{}, internalerrors.Wrap(internalerrors.KindValidation, "invalid URL", err)
		}
		return source.Origin{}, source.ErrNotHandled
	}
	if (parsed.Scheme == "http" || parsed.Scheme == "https") && (parsed.Fragment != "" || strings.Contains(input, "#")) {
		return source.Origin{}, internalerrors.Validation("URL must not contain a fragment")
	}
	match := ClassifyYouTubeURL(input)
	if parsed.Scheme == "http" || parsed.Scheme == "https" {
		if parsed.Host == "" {
			return source.Origin{}, internalerrors.Validation("URL must include a host")
		}
		if err := domain.ValidateSourceKey(input); err != nil {
			return source.Origin{}, err
		}
	}
	if match.Kind == YouTubeSupported {
		return source.NewOrigin(source.OriginYouTube, input, input), nil
	}
	if match.Kind == YouTubeUnsupported {
		return source.Origin{}, internalerrors.Source("YouTube URL: " + match.Reason)
	}
	if parsed.Scheme == "" {
		return source.Origin{}, source.ErrNotHandled
	}
	if parsed.Scheme != "http" && parsed.Scheme != "https" {
		return source.Origin{}, internalerrors.Validation("URL scheme must be http or https")
	}
	if parsed.Host == "" {
		return source.Origin{}, internalerrors.Validation("URL must include a host")
	}
	return source.NewOrigin(source.OriginHTML, input, parsed.String()), nil
}
package url

import (
	"bytes"
	"context"
	"fmt"
	"net/http"
	"strings"
	"unicode"

	htmltomarkdown "github.com/JohannesKaufmann/html-to-markdown/v2"
	"golang.org/x/net/html"

	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
	"github.com/skillicinski/bo/internal/source"
)

type HTMLPlugin struct {
	Client    Requester
	UserAgent string
}

func NewHTML(client Requester) *HTMLPlugin {
	return &HTMLPlugin{Client: client, UserAgent: DefaultUserAgent}
}

func (p *HTMLPlugin) Handle(ctx context.Context, origin source.Origin) (domain.RawSnapshot, error) {
	client := p.client()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, origin.Value, nil)
	if err != nil {
		return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindValidation, "invalid URL", err)
	}
	request.Header.Set("User-Agent", p.userAgent())
	response, err := client.Do(request)
	if err != nil {
		return domain.RawSnapshot{}, sourceFailure("request failed", err)
	}
	defer response.Body.Close()
	if response.StatusCode < 200 || response.StatusCode >= 300 {
		return domain.RawSnapshot{}, internalerrors.Source(fmt.Sprintf("source returned HTTP %d", response.StatusCode))
	}
	contentType := response.Header.Get("Content-Type")
	if !isHTMLContentType(contentType) {
		return domain.RawSnapshot{}, internalerrors.Source(fmt.Sprintf("not HTML (Content-Type: %s)", contentType))
	}
	body, err := source.ReadAll(response.Body)
	if err != nil {
		return domain.RawSnapshot{}, sourceFailure("reading response failed", err)
	}
	snapshot, err := ExtractHTML(string(body))
	if err != nil {
		return domain.RawSnapshot{}, err
	}
	snapshot.SourceKey = origin.SourceKey
	return snapshot, nil
}

func (p *HTMLPlugin) client() Requester {
	if p == nil || p.Client == nil {
		return http.DefaultClient
	}
	return p.Client
}

func (p *HTMLPlugin) userAgent() string {
	if p == nil || p.UserAgent == "" {
		return DefaultUserAgent
	}
	return p.UserAgent
}

func isHTMLContentType(value string) bool {
	mediaType := strings.ToLower(strings.TrimSpace(strings.SplitN(value, ";", 2)[0]))
	return mediaType == "text/html" || mediaType == "application/xhtml+xml"
}

var skippedTags = map[string]bool{
	"aside": true, "footer": true, "form": true, "header": true, "nav": true,
	"noscript": true, "script": true, "style": true, "svg": true, "template": true,
}

func ExtractHTML(input string) (domain.RawSnapshot, error) {
	document, err := html.Parse(strings.NewReader(input))
	if err != nil {
		return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindSource, "HTML parsing failed", err)
	}
	title := strings.Join(strings.Fields(textContent(findElement(document, "title"))), " ")
	if title == "" {
		return domain.RawSnapshot{}, internalerrors.Source("page has no title")
	}
	removeSkipped(document)
	for _, tag := range []string{"article", "main", "body"} {
		element := findElement(document, tag)
		if element == nil {
			continue
		}
		var rendered bytes.Buffer
		if err := html.Render(&rendered, element); err != nil {
			return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindSource, "HTML rendering failed", err)
		}
		markdown, err := htmltomarkdown.ConvertString(rendered.String())
		if err != nil {
			return domain.RawSnapshot{}, internalerrors.Wrap(internalerrors.KindSource, "HTML conversion failed", err)
		}
		markdown = removeMatchingTitleHeading(markdown, title)
		if hasAlphaNumeric(markdown) {
			return domain.NewRawSnapshot("", title, []byte(fmt.Sprintf("# %s\n\n%s\n", title, strings.TrimSpace(markdown)))), nil
		}
	}
	return domain.RawSnapshot{}, internalerrors.Source("page has no readable content")
}

func findElement(node *html.Node, wanted string) *html.Node {
	if node.Type == html.ElementNode && node.Data == wanted {
		return node
	}
	for child := node.FirstChild; child != nil; child = child.NextSibling {
		if found := findElement(child, wanted); found != nil {
			return found
		}
	}
	return nil
}

func textContent(node *html.Node) string {
	if node == nil {
		return ""
	}
	if node.Type == html.TextNode {
		return node.Data
	}
	var builder strings.Builder
	for child := node.FirstChild; child != nil; child = child.NextSibling {
		builder.WriteString(textContent(child))
	}
	return builder.String()
}

func removeSkipped(node *html.Node) {
	for child := node.FirstChild; child != nil; {
		next := child.NextSibling
		if child.Type == html.ElementNode && skippedTags[child.Data] {
			node.RemoveChild(child)
		} else {
			removeSkipped(child)
		}
		child = next
	}
}

func removeMatchingTitleHeading(markdown, title string) string {
	lines := strings.Split(markdown, "\n")
	if len(lines) == 0 {
		return ""
	}
	if strings.HasPrefix(lines[0], "# ") && strings.EqualFold(strings.TrimSpace(strings.TrimPrefix(lines[0], "# ")), strings.TrimSpace(title)) {
		lines = lines[1:]
	}
	return strings.TrimSpace(strings.Join(lines, "\n"))
}

func hasAlphaNumeric(value string) bool {
	for _, r := range value {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			return true
		}
	}
	return false
}

