func publicWorkflowTelemetry(telemetry []app.StageTelemetry) []WorkflowTelemetry {
	if len(telemetry) == 0 {
		return nil
	}
	result := make([]WorkflowTelemetry, len(telemetry))
	for index, stage := range telemetry {
		result[index] = WorkflowTelemetry{
			Workflow: stage.Workflow, SourceKey: stage.SourceKey,
			TerminalReason: stage.TerminalReason, TerminalDetail: stage.TerminalDetail,
			ProviderRetries: stage.ProviderRetries, ProviderRetryReasons: stage.ProviderRetryReasons,
		}
		if stage.Usage != nil {
			result[index].Usage = &TokenUsage{PromptTokens: stage.Usage.PromptTokens, CompletionTokens: stage.Usage.CompletionTokens, TotalTokens: stage.Usage.TotalTokens, ThoughtsTokens: stage.Usage.ThoughtsTokens}
		}
		if len(stage.ToolCalls) == 0 {
			continue
		}
		result[index].ToolCalls = make([]ToolCallTelemetry, len(stage.ToolCalls))
		for callIndex, call := range stage.ToolCalls {
			result[index].ToolCalls[callIndex] = ToolCallTelemetry{
				Turn: call.Turn, Index: call.Index, ID: call.ID, Name: call.Name,
				ArgumentsBytes: call.ArgumentsBytes, ArgumentsSHA256: call.ArgumentsSHA256,
				ArgumentsPreview: call.ArgumentsPreview, OutputBytes: call.OutputBytes,
				OutputReturnedBytes: call.OutputReturnedBytes, OutputSHA256: call.OutputSHA256,
				OutputTruncated: call.OutputTruncated, Error: call.Error,
			}
		}
	}
	return result
}

func publicOperationReport(operations []app.Operation) []OperationReport {
	reports := make([]OperationReport, 0, 2)
	for _, operation := range operations {
		if operation.Outcome != app.OutcomeCommitted || operation.Document == nil {
			continue
		}
		index := -1
		for reportIndex := range reports {
			if reports[reportIndex].Operation == OperationCommand(operation.Command) {
				index = reportIndex
				break
			}
		}
		if index == -1 {
			reports = append(reports, OperationReport{Operation: OperationCommand(operation.Command)})
			index = len(reports) - 1
		}
		document := DocumentIdentity{Kind: DocumentKind(operation.Document.Kind), Filename: operation.Document.Filename}
		duplicate := false
		for _, existing := range reports[index].Documents {
			if existing == document {
				duplicate = true
				break
			}
		}
		if !duplicate {
			reports[index].Documents = append(reports[index].Documents, document)
		}
	}
	return reports
}

func publicError(err error) error {
	if err == nil {
		return nil
	}
	var categorized *internalerrors.Error
	if stderrors.As(err, &categorized) {
		return &Error{
			Kind:      ErrorKind(categorized.Kind),
			Detail:    categorized.Detail,
			Retryable: categorized.Retryable,
			Cause:     err,
		}
	}
	if contextErr := internalerrors.Context(err); contextErr != nil {
		return &Error{
			Kind:      ErrorKind(contextErr.Kind),
			Detail:    contextErr.Detail,
			Retryable: contextErr.Retryable,
			Cause:     err,
		}
	}
	if stderrors.Is(err, internalerrors.ErrAlreadyExists) {
		return &Error{
			Kind:   ErrorKindAlreadyExists,
			Detail: "document already exists",
			Cause:  err,
		}
	}
	return err
}

func internalError(err error) error {
	if err == nil {
		return nil
	}
	var categorized *Error
	if stderrors.As(err, &categorized) {
		return &internalerrors.Error{
			Kind:      internalerrors.Kind(categorized.Kind),
			Detail:    categorized.Detail,
			Retryable: categorized.Retryable,
			Cause:     err,
		}
	}
	if stderrors.Is(err, ErrAlreadyExists) {
		return internalerrors.Wrap(internalerrors.KindAlreadyExists, "document already exists", err)
	}
	return err
}

func internalErrorAs(err error, kind internalerrors.Kind, detail string) error {
	converted := internalError(err)
	if converted == nil {
		return nil
	}
	var categorized *internalerrors.Error
	if stderrors.As(converted, &categorized) {
		return converted
	}
	if contextErr := internalerrors.Context(converted); contextErr != nil {
		return contextErr
	}
	return internalerrors.Wrap(kind, detail, converted)
}

