		Creator:    manager,
		Name:       options.name,
		Operations: bo.OperationOptions{Actor: "eval-harness"},
	})
	if err != nil {
		return emitError("capture", "", "", err)
	}
	workspace, err := manager.Open(ctx, seeded.Name)
	if err != nil {
		return emitError("capture", "", "", err)
	}
	defer workspace.Close()
	result, snapErr := bo.Snap(ctx, bo.SnapRequest{
		Workspace:  workspace,
		Sources:    sources,
		Operations: bo.OperationOptions{Actor: "eval-harness"},
	})
