package application

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/skillicinski/bo/internal/agent"
	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
)

func Synthesize(ctx context.Context, workspace Workspace, provider agent.CompletionProvider, config SynthesisOptions, options OperationOptions) (SynthesisResult, error) {
	return SynthesizeWithTools(ctx, workspace, provider, config, allSynthesisTools, options)
}

func SynthesizeWithTools(ctx context.Context, workspace Workspace, provider agent.CompletionProvider, config SynthesisOptions, toolNames []string, options OperationOptions) (result SynthesisResult, returnErr error) {
	options = normalizeOperationOptions(options)
	var err error
	toolNames, err = normalizeSynthesisTools(toolNames)
	if err != nil {
		return SynthesisResult{}, synthFailure(ctx, workspace, options.Actor, internalerrors.Validation(err.Error()))
	}
	if workspace == nil {
		return SynthesisResult{}, internalerrors.Request("workspace is not configured")
	}
	result, returnErr = runSynthesis(ctx, workspace, provider, config, toolNames, options)
	operation := newOperation(CommandSynth, options.Actor)
	operation.Metrics = &domain.OperationMetrics{
		Turns: result.Metrics.Turns, ToolCalls: result.Metrics.ToolCalls, Duration: result.Metrics.Duration,
		SummariesWritten: result.SummariesWritten, SummariesSkipped: result.SummariesSkipped,
	}
	if result.Metrics.Usage != nil {
		operation.Metrics.Usage = &domain.TokenUsage{
			PromptTokens: result.Metrics.Usage.PromptTokens, CompletionTokens: result.Metrics.Usage.CompletionTokens, TotalTokens: result.Metrics.Usage.TotalTokens, ThoughtsTokens: result.Metrics.Usage.ThoughtsTokens,
		}
	}
	if returnErr == nil {
		operation = committedOperation(operation)
	} else {
		operation = failedOperation(operation, returnErr)
	}
	if eventErr := commitOperationEvent(ctx, workspace, operation); eventErr != nil {
		returnErr = errors.Join(returnErr, eventErr)
	}
	return result, returnErr
}

func synthFailure(ctx context.Context, workspace Workspace, actor string, cause error) error {
	operation := failedOperation(newOperation(CommandSynth, actor), cause)
	if workspace != nil {
		if err := commitOperationEvent(ctx, workspace, operation); err != nil {
			return errors.Join(cause, err)
		}
		return cause
	}
	return cause
}

func runSynthesis(ctx context.Context, workspace Workspace, provider agent.CompletionProvider, config SynthesisOptions, toolNames []string, options OperationOptions) (SynthesisResult, error) {
	if workspace == nil {
		return SynthesisResult{}, internalerrors.Request("workspace is not configured")
	}
	if provider == nil {
		return SynthesisResult{}, internalerrors.Request("synthesis provider is not configured")
	}
	config = normalizedSynthesisOptions(config)
	documents, err := DiscoverDocuments(ctx, workspace)
	if err != nil {
		return SynthesisResult{}, err
	}
	if len(documents) == 0 {
		return SynthesisResult{}, internalerrors.MissingResource("no raw Markdown documents in workspace")
	}
	written := map[string]bool{}
	skipped := map[string]bool{}
	result := SynthesisResult{}
	usageKnown, usageReceived := true, false
	var usage agent.TokenUsage
	var events []Operation
	readLogsEnabled := false
	for _, name := range toolNames {
		if name == toolReadLogs {
			readLogsEnabled = true
			break
		}
	}
	eventsLoaded := !readLogsEnabled
	state, revision, err := workspace.ReadState(ctx)
	if err != nil {
		return result, normalizeError(err, internalerrors.KindFilesystem, "reading workspace state")
	}
	for {
		sources := sourceGroups(documents, state)
		completed := completedSynthesisSources(state, sources)
		for sourceKey := range skipped {
			if !completed[sourceKey] {
				delete(skipped, sourceKey)
			}
		}
		for sourceKey := range completed {
			if !written[sourceKey] {
				skipped[sourceKey] = true
			}
		}
		pending := missingSources(sources, completed)
		if len(pending) == 0 {
			break
		}
		if readLogsEnabled && !eventsLoaded {
			events, err = readRecentSynthesisEvents(ctx, workspace)
			if err != nil {
				return result, err
			}
			eventsLoaded = true
		}
		sourceKey := pending[0]
		sourceSources := map[string]agentSource{sourceKey: sources[sourceKey]}
		contextState := &agentContext{
			ctx: ctx, workspace: workspace, documents: documents, sources: sourceSources,
			state: state, revision: revision, maxOutputBytes: config.MaxToolOutputBytes,
			directory: workspace.Name(), options: options,
			completed: map[string]bool{}, written: map[string]bool{}, mutationOps: map[string]Operation{},
		}
		if readLogsEnabled {
			contextState.logEvents = scopedSynthesisEvents(events, sourceSources)
			contextState.logWindowLoaded = true
		}
		names := []string{sourceSources[sourceKey].LatestFilename}
		messages := []agent.ChatMessage{
			{Role: "system", Content: systemPrompt(contextState, names, readLogsEnabled)},
			{Role: "user", Content: fmt.Sprintf("Produce one concise Markdown summary for every source identity. Use the newest raw snapshot as evidence and preserve each source's epistemic status. Source identities: %s", sourceKey)},
		}
		runtime := agent.Runtime{
			Provider: provider,
			Tools:    synthTools(contextState, toolNames),
			Done: func() bool {
				return len(contextState.completed) == len(sourceSources)
			},
		}
		runtimeContext, cancel := context.WithTimeout(ctx, time.Duration(config.RuntimeTimeoutSeconds)*time.Second)
		contextState.ctx = runtimeContext
		runtimeResult, runtimeErr := runtime.Run(runtimeContext, messages, agent.Options{
			MaxTurns: config.MaxTurns, MaxToolCalls: config.MaxToolCalls,
			MaxToolOutputBytes: config.MaxToolOutputBytes, MaxResponseTokens: config.MaxResponseTokens,
		})
		cancel()
		terminalDetail := ""
		if runtimeErr != nil {
			terminalDetail = runtimeErr.Error()
		}
		result.Telemetry = append(result.Telemetry, StageTelemetry{
			Workflow: "summarize", SourceKey: sourceKey, TerminalReason: runtimeResult.Telemetry.TerminalReason,
			TerminalDetail: terminalDetail, ProviderRetries: runtimeResult.Telemetry.ProviderRetries,
			ProviderRetryReasons: runtimeResult.Telemetry.ProviderRetryReasons, Usage: runtimeResult.Metrics.Usage,
			ToolCalls: runtimeResult.Telemetry.ToolCalls,
		})
		result.Metrics.Turns += runtimeResult.Metrics.Turns
		result.Metrics.ToolCalls += runtimeResult.Metrics.ToolCalls
		result.Metrics.Duration += runtimeResult.Metrics.Duration
		if runtimeResult.Metrics.Usage == nil {
			usageKnown = false
		} else if usageKnown {
			usage.PromptTokens += runtimeResult.Metrics.Usage.PromptTokens
			usage.CompletionTokens += runtimeResult.Metrics.Usage.CompletionTokens
			usage.TotalTokens += runtimeResult.Metrics.Usage.TotalTokens
			usage.ThoughtsTokens += runtimeResult.Metrics.Usage.ThoughtsTokens
			usageReceived = true
		}
		for sourceKey := range contextState.written {
			written[sourceKey] = true
			delete(skipped, sourceKey)
		}
		result.Committed = append(result.Committed, contextState.committed...)
		for sourceKey := range contextState.completed {
			if !contextState.written[sourceKey] && !written[sourceKey] {
				skipped[sourceKey] = true
			}
		}
		result.Metrics.Usage = aggregateUsage(usage, usageKnown, usageReceived)
		result.SummariesWritten, result.SummariesSkipped = len(written), len(skipped)
		if contextState.eventFailure != nil {
			if runtimeErr != nil {
				return result, errors.Join(contextState.eventFailure, runtimeErr)
			}
			return result, contextState.eventFailure
		}
		if runtimeErr != nil {
			return result, runtimeErr
		}
		if len(contextState.completed) != len(sourceSources) {
			return result, internalerrors.ProviderMalformed(fmt.Sprintf("model stopped with missing summaries: %s", strings.Join(missingSources(sourceSources, contextState.completed), ", ")), nil)
		}
		if len(pending) == 1 {
			break
		}
		state, revision, err = workspace.ReadState(ctx)
		if err != nil {
			result.Metrics.Usage = aggregateUsage(usage, usageKnown, usageReceived)
			result.SummariesWritten, result.SummariesSkipped = len(written), len(skipped)
			return result, normalizeError(err, internalerrors.KindFilesystem, "reading workspace state")
		}
	}
	result.Metrics.Usage = aggregateUsage(usage, usageKnown, usageReceived)
	result.SummariesWritten, result.SummariesSkipped = len(written), len(skipped)
	return result, nil
}
func aggregateUsage(usage agent.TokenUsage, known, received bool) *agent.TokenUsage {
	if !known || !received {
		return nil
	}
	return &agent.TokenUsage{PromptTokens: usage.PromptTokens, CompletionTokens: usage.CompletionTokens, TotalTokens: usage.TotalTokens, ThoughtsTokens: usage.ThoughtsTokens}
}

const synthesisEventWindow = MaxOperationPageLimit

func readRecentSynthesisEvents(ctx context.Context, workspace Workspace) ([]Operation, error) {
	events, err := workspace.ReadRecentEvents(ctx, synthesisEventWindow)
	if err != nil {
		return nil, normalizeError(err, internalerrors.KindFilesystem, "reading recent operation log")
	}
	if len(events) > synthesisEventWindow {
		return nil, internalerrors.Validation("recent operation log exceeds its fixed window")
	}
	for index, event := range events {
		if err := event.Validate(); err != nil {
			return nil, internalerrors.Wrap(internalerrors.KindValidation, fmt.Sprintf("recent operation log entry %d is invalid", index), err)
		}
	}
	return events, nil
}

func completedSynthesisSources(state domain.State, sources map[string]agentSource) map[string]bool {
	completed := make(map[string]bool, len(sources))
	for sourceKey, source := range sources {
		summary := summaryRecord(state, sourceKey)
		if summary != nil && summary.DerivedFrom == source.LatestFilename {
			completed[sourceKey] = true
		}
	}
	return completed
}

func missingSources(sources map[string]agentSource, summarized map[string]bool) []string {
	missing := make([]string, 0)
	for sourceKey := range sources {
		if !summarized[sourceKey] {
			missing = append(missing, sourceKey)
		}
	}
	sort.Strings(missing)
	return missing
}

func normalizedSynthesisOptions(config SynthesisOptions) SynthesisOptions {
	defaults := DefaultSynthesisOptions()
	if config.MaxTurns <= 0 {
		config.MaxTurns = defaults.MaxTurns
	}
	if config.MaxToolCalls <= 0 {
		config.MaxToolCalls = defaults.MaxToolCalls
	}
	if config.MaxToolOutputBytes <= 0 {
		config.MaxToolOutputBytes = defaults.MaxToolOutputBytes
	}
	if config.MaxResponseTokens <= 0 {
		config.MaxResponseTokens = defaults.MaxResponseTokens
	}
	if config.RuntimeTimeoutSeconds <= 0 {
		config.RuntimeTimeoutSeconds = defaults.RuntimeTimeoutSeconds
	}
	return config
}
package application

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/skillicinski/bo/internal/agent"
	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
)

type DistillRequest struct {
	Workspace  Workspace
	Provider   agent.CompletionProvider
	Options    SynthesisOptions
	ToolNames  []string
	Operations OperationOptions
}

type DistillResult struct {
	Filename  string           `json:"filename,omitempty"`
	Skipped   bool             `json:"skipped"`
	Reason    string           `json:"reason,omitempty"`
	Committed []Operation      `json:"-"`
	Filenames []string         `json:"-"`
	Metrics   agent.Metrics    `json:"metrics"`
	Telemetry []StageTelemetry `json:"telemetry,omitempty"`
}

func Distill(ctx context.Context, workspace Workspace, provider agent.CompletionProvider, config SynthesisOptions, options OperationOptions) (DistillResult, error) {
	return DistillWithTools(ctx, workspace, provider, config, allDistillTools, options)
}

func DistillWithTools(ctx context.Context, workspace Workspace, provider agent.CompletionProvider, config SynthesisOptions, toolNames []string, options OperationOptions) (result DistillResult, returnErr error) {
	options = normalizeOperationOptions(options)
	var err error
	toolNames, err = normalizeDistillTools(toolNames)
	if err != nil {
		return DistillResult{}, distillFailure(ctx, workspace, options.Actor, internalerrors.Validation(err.Error()))
	}
	if workspace == nil {
		return DistillResult{}, internalerrors.Request("workspace is not configured")
	}
	result, returnErr = runDistill(ctx, workspace, provider, config, toolNames, options)
	written := distillationCount(result)
	operation := newOperation(CommandDistill, options.Actor)
	operation.Metrics = &domain.OperationMetrics{
		Turns: result.Metrics.Turns, ToolCalls: result.Metrics.ToolCalls, Duration: result.Metrics.Duration,
		DistillationWritten: written, DistillationSkipped: boolCount(result.Skipped && written == 0),
	}
	if result.Metrics.Usage != nil {
		operation.Metrics.Usage = &domain.TokenUsage{
			PromptTokens: result.Metrics.Usage.PromptTokens, CompletionTokens: result.Metrics.Usage.CompletionTokens, TotalTokens: result.Metrics.Usage.TotalTokens, ThoughtsTokens: result.Metrics.Usage.ThoughtsTokens,
		}
	}
	if returnErr == nil {
		operation = committedOperation(operation)
	} else {
		operation = failedOperation(operation, returnErr)
	}
	if eventErr := commitOperationEvent(ctx, workspace, operation); eventErr != nil {
		returnErr = errors.Join(returnErr, eventErr)
	}
	return result, returnErr
}

func boolCount(value bool) int {
	if value {
		return 1
	}
	return 0
}

func distillationCount(result DistillResult) int {
	if len(result.Filenames) > 0 {
		return len(result.Filenames)
	}
	return boolCount(result.Filename != "")
}

func distillFailure(ctx context.Context, workspace Workspace, actor string, cause error) error {
	operation := failedOperation(newOperation(CommandDistill, actor), cause)
	if workspace == nil {
		return cause
	}
	if err := commitOperationEvent(ctx, workspace, operation); err != nil {
		return errors.Join(cause, err)
	}
	return cause
}

func runDistill(ctx context.Context, workspace Workspace, provider agent.CompletionProvider, config SynthesisOptions, toolNames []string, options OperationOptions) (DistillResult, error) {
	if workspace == nil {
		return DistillResult{}, internalerrors.Request("workspace is not configured")
	}
	if provider == nil {
		return DistillResult{}, internalerrors.Request("distill provider is not configured")
	}
	config = normalizedSynthesisOptions(config)
	state, revision, err := workspace.ReadState(ctx)
	if err != nil {
		return DistillResult{}, normalizeError(err, internalerrors.KindFilesystem, "reading workspace state")
	}
	catalog, err := buildDistillCatalog(ctx, workspace, state)
	if err != nil {
		return DistillResult{}, err
	}
	if len(catalog.sources) == 0 {
		return DistillResult{}, internalerrors.MissingResource("no current raw Markdown documents in workspace")
	}
	if len(catalog.sources) < 2 {
		return DistillResult{
			Skipped: true, Reason: "at least two source identities are required",
			Telemetry: []StageTelemetry{{Workflow: "distill", TerminalReason: "precondition", TerminalDetail: "at least two source identities are required"}},
		}, nil
	}
	result := DistillResult{}
	readLogsEnabled := false
	for _, name := range toolNames {
		if name == toolReadLogs {
			readLogsEnabled = true
			break
		}
	}
	var events []Operation
	if readLogsEnabled {
		events, err = readRecentSynthesisEvents(ctx, workspace)
		if err != nil {
			return DistillResult{}, err
		}
	}
	contextState := &distillContext{
		directory: workspace.Name(), workspace: workspace, options: options,
		catalog: catalog, state: state, revision: revision, maxOutputBytes: config.MaxToolOutputBytes,
		readDocuments: map[string][]byte{}, readRefs: map[string]bool{}, readDistillations: map[string]bool{}, mutationOps: map[string]Operation{},
	}
	for _, name := range toolNames {
		if name == toolReadSummary {
			contextState.summaryToolEnabled = true
			break
		}
	}
	if readLogsEnabled {
		contextState.logEvents = scopedSynthesisEvents(events, catalog.sources)
		contextState.logWindowLoaded = true
	}
	names := make([]string, 0, len(catalog.sources))
	for _, source := range catalog.sources {
		names = append(names, source.LatestFilename)
	}
	sort.Strings(names)
	keys := make([]string, 0, len(catalog.sources))
	for sourceKey := range catalog.sources {
		keys = append(keys, sourceKey)
	}
	sort.Strings(keys)
	message := fmt.Sprintf("Process every useful cross-source theme supported by at least two distinct source identities. For a new topic, call write_distillation once; for an existing topic with changed evidence, call edit_distillation once after reading it. When no unprocessed theme remains, call skip_distill exactly once. Current source identities: %s. Latest raw documents: %s.", strings.Join(keys, ", "), strings.Join(names, ", "))
	runtime := agent.Runtime{
		Provider: provider,
		Tools:    distillTools(contextState, toolNames),
		Done: func() bool {
			return contextState.skipped
		},
	}
	runtimeContext, cancel := context.WithTimeout(ctx, time.Duration(config.RuntimeTimeoutSeconds)*time.Second)
	contextState.ctx = runtimeContext
	runtimeResult, runtimeErr := runtime.Run(runtimeContext, []agent.ChatMessage{
		{Role: "system", Content: distillSystemPrompt(contextState, readLogsEnabled)},
		{Role: "user", Content: message},
	}, agent.Options{
		MaxTurns: config.MaxTurns, MaxToolCalls: config.MaxToolCalls,
		MaxToolOutputBytes: config.MaxToolOutputBytes, MaxResponseTokens: config.MaxResponseTokens,
	})
	cancel()
	terminalDetail := contextState.reason
	if runtimeErr != nil {
		terminalDetail = runtimeErr.Error()
	}
	result.Telemetry = append(result.Telemetry, StageTelemetry{
		Workflow: "distill", TerminalReason: runtimeResult.Telemetry.TerminalReason,
		TerminalDetail: terminalDetail, ProviderRetries: runtimeResult.Telemetry.ProviderRetries,
		ProviderRetryReasons: runtimeResult.Telemetry.ProviderRetryReasons, Usage: runtimeResult.Metrics.Usage,
		ToolCalls: runtimeResult.Telemetry.ToolCalls,
	})
	result.Metrics = runtimeResult.Metrics
	result.Committed = append(result.Committed, contextState.committed...)
	result.Filenames = append(result.Filenames, contextState.filenames...)
	if contextState.eventFailure != nil {
		if runtimeErr != nil {
			return result, errors.Join(contextState.eventFailure, runtimeErr)
		}
		return result, contextState.eventFailure
	}
	if runtimeErr != nil {
		return result, runtimeErr
	}
	if !contextState.skipped {
		return result, internalerrors.ProviderMalformed("model stopped without skip_distill", nil)
	}
	if len(result.Filenames) > 0 {
		result.Filename = result.Filenames[len(result.Filenames)-1]
	} else {
		result.Filename = contextState.filename
	}
	result.Skipped = contextState.skipped && len(result.Filenames) == 0
	result.Reason = contextState.reason
	return result, nil
}
package application

import (
	"context"
	"errors"
	"fmt"
	"time"

	"github.com/skillicinski/bo/internal/domain"
	internalerrors "github.com/skillicinski/bo/internal/errors"
	"github.com/skillicinski/bo/internal/source"
)

type SnapOutcome struct {
	SourceKey string
	Filename  string
	Err       error
}

type SnapCommandError struct {
	Completed []SnapOutcome
	SourceKey string
	Err       error
}

// ponytail: cap collisions at 8; use workspace-side filename reservation if collisions become common.
const maxRawCommitAttempts = 8

func (e *SnapCommandError) Error() string {
	if e.SourceKey != "" && e.Err != nil {
		return fmt.Sprintf("%s (%s)", e.SourceKey, e.Err)
	}
	if e.Err != nil {
		return e.Err.Error()
	}
	return "snap failed"
}

func (e *SnapCommandError) Unwrap() error { return e.Err }

func NewSnapInputError(detail string) *SnapCommandError {
	return &SnapCommandError{Err: internalerrors.Validation(detail)}
}

func Snap(ctx context.Context, workspace Workspace, workflow source.Fetcher, inputs []string, options OperationOptions) ([]SnapOutcome, error) {
	options = normalizeOperationOptions(options)
	if workspace == nil {
		return nil, snapWorkflowFailure(ctx, nil, options, internalerrors.Request("workspace is not configured"))
	}
	if len(inputs) == 0 {
		return nil, snapWorkflowFailure(ctx, workspace, options, NewSnapInputError("at least one source is required"))
	}
	if workflow == nil {
		return nil, snapWorkflowFailure(ctx, workspace, options, NewSnapInputError("source workflow is not configured"))
	}
	_, revision, err := workspace.ReadState(ctx)
	if err != nil {
		err = normalizeError(err, internalerrors.KindFilesystem, "reading workspace state")
		operation := newOperation(CommandSnap, options.Actor)
		eventErr := snapFailureEvent(ctx, workspace, operation, err)
		return nil, &SnapCommandError{Err: errors.Join(err, eventErr)}
	}
	outcomes := make([]SnapOutcome, 0, len(inputs))
	for index, input := range inputs {
		operation := newOperation(CommandSnap, options.Actor)
		if domain.ValidateSourceKey(input) == nil {
			operation.Source = &domain.SourceIdentity{SourceKey: input}
		}
		snapshot, fetchErr := workflow.Fetch(ctx, input)
		if fetchErr != nil {
			fetchErr = normalizeError(fetchErr, internalerrors.KindSource, "fetching source")
			failureErr := snapFailureEvent(ctx, workspace, operation, fetchErr)
			if failureErr != nil {
				return outcomes, &SnapCommandError{Completed: outcomes, SourceKey: input, Err: errors.Join(fetchErr, failureErr)}
			}
			if isTerminalContextError(fetchErr) {
				return outcomes, &SnapCommandError{Completed: outcomes, SourceKey: input, Err: fetchErr}
			}
			outcomes = append(outcomes, SnapOutcome{SourceKey: input, Err: fetchErr})
			continue
		}
		sourceKey := snapshot.SourceKey
		if sourceKey == "" {
			sourceKey = input
		}
		if sourceErr := domain.ValidateSourceKey(sourceKey); sourceErr != nil {
			sourceErr = normalizeError(sourceErr, internalerrors.KindValidation, "validating source key")
			failureErr := snapFailureEvent(ctx, workspace, operation, sourceErr)
			if failureErr != nil {
				return outcomes, &SnapCommandError{Completed: outcomes, SourceKey: input, Err: errors.Join(sourceErr, failureErr)}
			}
			outcomes = append(outcomes, SnapOutcome{SourceKey: input, Err: sourceErr})
			continue
		}
		operation.Source = &domain.SourceIdentity{SourceKey: sourceKey}
		slug, slugErr := KebabCase(snapshot.Title)
		if slugErr != nil {
			slugErr = normalizeError(slugErr, internalerrors.KindValidation, "creating snapshot filename")
			failureErr := snapFailureEvent(ctx, workspace, operation, slugErr)
			if failureErr != nil {
				return outcomes, &SnapCommandError{Completed: outcomes, SourceKey: input, Err: errors.Join(slugErr, failureErr)}
			}
			outcomes = append(outcomes, SnapOutcome{SourceKey: input, Err: slugErr})
			continue
		}
		writtenAt := time.Now().UTC()
		filename, newRevision, writeErr := createRaw(ctx, workspace, revision, sourceKey, slug, writtenAt, snapshot.Markdown, operation)
		if writeErr != nil {
			batchErr := writeErr
			if !isTerminalContextError(writeErr) {
				for _, skipped := range inputs[index+1:] {
					skippedOperation := newOperation(CommandSnap, options.Actor)
					if domain.ValidateSourceKey(skipped) == nil {
						skippedOperation.Source = &domain.SourceIdentity{SourceKey: skipped}
					}
					if failureErr := snapFailureEvent(ctx, workspace, skippedOperation, fmt.Errorf("snap batch aborted after %s", input)); failureErr != nil {
						batchErr = errors.Join(batchErr, failureErr)
						break
					}
				}
			}
			return outcomes, &SnapCommandError{Completed: outcomes, SourceKey: input, Err: batchErr}
		}
		revision = newRevision
		outcomes = append(outcomes, SnapOutcome{SourceKey: sourceKey, Filename: filename})
	}
	return outcomes, nil
}

func createRaw(ctx context.Context, workspace Workspace, revision Revision, sourceKey, slug string, writtenAt time.Time, contents []byte, operation Operation) (string, Revision, error) {
	for attempt := 1; ; attempt++ {
		filename := slug + ".md"
		if attempt == 2 {
			filename = fmt.Sprintf("%s--%d.md", slug, writtenAt.UnixNano())
		} else if attempt > 2 {
			filename = fmt.Sprintf("%s--%d--%d.md", slug, writtenAt.UnixNano(), attempt)
		}
		attemptOperation := operation
		attemptOperation.Attempt = attempt
		attemptOperation.Document = &domain.DocumentIdentity{Kind: domain.DocumentKindRaw, Filename: filename}
		if err := ctx.Err(); err != nil {
			contextErr := internalerrors.Context(err)
			if eventErr := recordFailedOperation(ctx, workspace, attemptOperation, contextErr); eventErr != nil {
				return "", revision, errors.Join(contextErr, eventErr)
			}
			return "", revision, contextErr
		}
		committed := committedOperation(attemptOperation)
		commit := SnapshotCommit{SourceKey: sourceKey, Filename: filename, WrittenAt: writtenAt, Contents: contents, Event: committed}
		_, newRevision, err := workspace.CommitSnapshot(ctx, commit, revision)
		if err == nil {
			return filename, newRevision, nil
		}
		if eventErr := recordFailedOperation(ctx, workspace, attemptOperation, err); eventErr != nil {
			return "", revision, errors.Join(err, eventErr)
		}
		if isTerminalContextError(err) {
			return "", Revision{}, err
		}
		if !internalerrors.IsAlreadyExists(err) {
			return "", Revision{}, err
		}
		if attempt == maxRawCommitAttempts {
			return "", Revision{}, internalerrors.Wrap(internalerrors.KindAlreadyExists, "raw document filename attempts exhausted", err)
		}
	}
}

func isTerminalContextError(err error) bool {
	return errors.Is(err, context.Canceled) || errors.Is(err, context.DeadlineExceeded)
}

func snapFailureEvent(ctx context.Context, workspace Workspace, operation Operation, cause error) error {
	return recordFailedOperation(ctx, workspace, operation, cause)
}

func snapWorkflowFailure(ctx context.Context, workspace Workspace, options OperationOptions, cause error) error {
	if workspace != nil {
		if err := recordFailedOperation(ctx, workspace, newOperation(CommandSnap, options.Actor), cause); err != nil {
			return errors.Join(cause, err)
		}
		return cause
	}
	return cause
}

