	home := t.TempDir()
	if err := os.MkdirAll(filepath.Join(home, ".bo", "first"), 0o700); err != nil {
		t.Fatal(err)
	}
	calls := setWorkspaceNames(t, "first", "second")
	target, err := Seed(home, nil)
	if err != nil {
		t.Fatal(err)
	}
