		t.Fatal(err)
	}
	if err := os.Remove(transactionMarker); err != nil {
		t.Fatal(err)
	}
	page, err := store.ReadEvents(context.Background(), 0, 20)
	if err != nil {
		t.Fatal(err)
	}
	for _, event := range page.Entries {
